// =============================================================================================
// The ground under a drop, the shop's own latch, and the salvage window's drag-out.
// =============================================================================================

use dereth_client::character::{Character, CharacterInput};
use dereth_client::interaction::{self, Interaction};
use dereth_client::objects::ObjectStream;
use dereth_client::world::{load_region, DEFAULT_LANDBLOCK};
use dereth_client_model::Request;
use dereth_client_net::client_session::testing::{Corpus, MockTransport};
use dereth_client_net::client_session::Session;
use dereth_primitives::ServerTime;
use dereth_ui_screens::hud::speech_bubbles::LIST_BOX;
use dereth_ui_screens::items::widget::{drag_flags, inq_drop_icon_info};
use dereth_ui_screens::panels::salvage::{self, ButtonState as SalvageButton};
use dereth_ui_screens::view::{DropTarget, UiRequest};
use std::sync::Arc;

/// The refusal the client prints when a drop would leave something in the air, as a literal --
/// a scenario that read it through the symbol it is written through could not catch a wrong one.
const MID_AIR: &str = "You cannot do that in mid air";
/// The one-thing-at-a-time refusal, likewise verbatim: it is the sentence a player reads.
const BUSY: &str = "You can only move or use one item at a time";
/// The channel the client's own inventory feedback goes out on.
const FEEDBACK_CHANNEL: u32 = 0x1A;
/// The middle of the landblock the headless client starts on.
const SPAWN: (f32, f32) = (96.0, 96.0);

// ---------------------------------------------------------------------------------------------
// o417: the ground under a world drop.
// ---------------------------------------------------------------------------------------------

/// A body standing still on the retail terrain, settled for two seconds of frames.
fn a_settled_body(store: &Arc<dereth_dat::RetailDatStore>) -> Character {
    let region = load_region(store).expect("the region decodes");
    let mut c = Character::new(store, &region, DEFAULT_LANDBLOCK, SPAWN).expect("a body");
    for i in 1..=60 {
        c.update(dereth_primitives::LocalTime(f64::from(i) / 30.0));
    }
    assert!(
        c.on_ground(),
        "the premise: the body settles before anything is measured"
    );
    c
}

/// The same body, in the air -- through the body's own input, not by writing a bit.
fn jump(c: &mut Character, from_frame: u32) {
    let mut f = from_frame;
    c.input = CharacterInput {
        jump: true,
        ..CharacterInput::default()
    };
    f += 1;
    c.update(dereth_primitives::LocalTime(f64::from(f) / 30.0));
    c.input = CharacterInput::default();
    for _ in 0..2 {
        f += 1;
        c.update(dereth_primitives::LocalTime(f64::from(f) / 30.0));
    }
    assert!(
        !c.on_ground(),
        "the premise: the jump took the body off the ground"
    );
}

/// A player and the things this pair of scenarios drops, in a world of their own.
///
/// It is not the scenario client's world because the gesture has to be driven with a body the
/// scenario made and put into a jump, and the client's own body is the one its frame simulates.
struct DropHost {
    store: Arc<dereth_dat::RetailDatStore>,
    objects: ObjectStream,
    inter: Interaction,
    player: ObjectId,
    clock: f64,
}

impl DropHost {
    fn new(store: &Arc<dereth_dat::RetailDatStore>) -> Self {
        let mut objects = ObjectStream::new();
        let player = ObjectId(0x5000_0417);
        objects.world.player = Some(player);
        objects.world.tables.inventories.insert(
            player,
            dereth_client_model::objects::ObjectInventory::new(player),
        );
        let mut pw = dereth_client_model::Weenie::new(player);
        pw.pwd.items_capacity = Some(0xFF);
        pw.pwd.containers_capacity = Some(0xFF);
        objects.world.tables.weenies.insert(player, pw);
        let mut h = Self {
            store: Arc::clone(store),
            objects,
            inter: Interaction::new(),
            player,
            clock: 1.0,
        };
        h.frame();
        h
    }

    /// One frame of the client's own use-time pass, which is what reads the body every frame.
    fn frame(&mut self) {
        self.clock += 1.0;
        let _ = interaction::use_time(
            &mut self.inter,
            &self.store,
            None,
            &mut self.objects,
            None,
            Vec::new(),
            false,
            (1024, 768),
            dereth_primitives::LocalTime(self.clock),
        );
    }

    fn carry(&mut self, id: ObjectId) -> ObjectId {
        let mut w = dereth_client_model::Weenie::new(id);
        w.pwd.container_id = Some(self.player);
        w.pwd.stack_size = Some(1);
        w.pwd.max_stack_size = Some(1);
        w.pwd.name = format!("thing {:X}", id.0);
        w.waiting = true;
        w.determine_position_state();
        self.objects.world.tables.weenies.insert(id, w);
        assert!(
            self.objects.world.is_owned_by_player(id),
            "the premise: it is being carried"
        );
        id
    }

    fn a_creature(&mut self, id: ObjectId) -> ObjectId {
        let mut w = dereth_client_model::Weenie::new(id);
        w.pwd.obj_type = dereth_client_model::weenie::item_type::CREATURE;
        w.pwd.name = "Ulgrim".to_owned();
        self.objects.world.tables.weenies.insert(id, w);
        id
    }

    /// The whole gesture, with the body handed to the production producer at the point the
    /// frame's own pass hands it over.
    fn drop_onto(
        &mut self,
        item: ObjectId,
        found: ObjectId,
        body: Option<&Character>,
    ) -> Vec<dereth_client_model::Request> {
        self.inter.queue(
            Vec::new(),
            vec![UiRequest::DragDrop {
                item,
                target: DropTarget::World,
            }],
        );
        self.clock += 1.0;
        let unowned =
            self.inter
                .run_ui_requests(&mut self.objects.world, false, ServerTime(self.clock));
        assert!(unowned.is_empty(), "the world-drop arm owns the gesture");
        assert!(
            self.inter.pick.looking_for_object(),
            "the premise: the pick is armed"
        );
        assert!(
            self.inter.pending_requests().is_empty(),
            "the premise: nothing is built before the answer"
        );

        self.clock += 1.0;
        self.inter.note_player_physics(body);
        self.inter
            .on_world_object_found(found, &mut self.objects.world, ServerTime(self.clock));
        self.inter.pending_requests().to_vec()
    }

    fn lines(&self) -> Vec<(u32, String)> {
        self.objects
            .world
            .scroll
            .pending()
            .iter()
            .map(|f| (f.chat_type, f.body.clone()))
            .collect()
    }
}

fn is_drop(r: &dereth_client_model::Request) -> bool {
    matches!(r, dereth_client_model::Request::DropItem(_))
}

fn is_give(r: &dereth_client_model::Request) -> bool {
    matches!(r, dereth_client_model::Request::GiveObjectRequest(_))
}

/// A client over the retail data, with no shell: what these scenarios want from it is the dat
/// store the terrain comes out of, and the place to book the claim.
fn a_retail_client() -> HeadlessClient {
    HeadlessClient::new(ClientSpec::retail())
}

/// A drop into the world is refused in the air and allowed on the ground, from one body.
pub fn a_world_drop_is_refused_in_mid_air() {
    let mut c = a_retail_client();
    let store = Arc::clone(c.dat_store().expect("a retail client opens the dats"));
    let mut body = a_settled_body(&store);

    // On the ground.
    let mut host = DropHost::new(&store);
    let item = host.carry(ObjectId(0x2883_0001));
    let out = host.drop_onto(item, ObjectId(0), Some(&body));
    let standing = host.inter.player_on_ground() == Some(true)
        && out.len() == 1
        && is_drop(&out[0])
        && host.lines().is_empty();

    // The same body, airborne. **The two arms differ in nothing but the jump**, which is what
    // makes this discriminating rather than a pair of one-sided measurements.
    jump(&mut body, 60);
    let mut host = DropHost::new(&store);
    let item = host.carry(ObjectId(0x2883_0002));
    let out = host.drop_onto(item, ObjectId(0), Some(&body));
    let airborne = host.inter.player_on_ground() == Some(false)
        && out.is_empty()
        && host.lines() == vec![(FEEDBACK_CHANNEL, MID_AIR.to_owned())]
        && !host.objects.world.weenie(item).expect("seeded").waiting
        // The producer moved, rather than having been constant and lucky.
        && host.inter.stats.physics_answers_changed > 0;

    // …and a client with no body at all is treated exactly as one in the air.
    let mut host = DropHost::new(&store);
    let item = host.carry(ObjectId(0x2883_0020));
    let out = host.drop_onto(item, ObjectId(0), None);
    let bodiless = host.inter.player_on_ground().is_none()
        && out.is_empty()
        && host.lines() == vec![(FEEDBACK_CHANNEL, MID_AIR.to_owned())];

    c.assert_behaviour(
        "inventory.world-drop.a-player-in-mid-air-is-refused-and-one-on-the-ground-is-not",
        move |_| standing && airborne && bodiless,
    );
    c.shutdown();
}

/// Handing something over while falling is not refused -- the gate is downstream of that arm.
pub fn a_give_in_mid_air_is_not_refused() {
    let mut c = a_retail_client();
    let store = Arc::clone(c.dat_store().expect("a retail client opens the dats"));
    let mut body = a_settled_body(&store);
    jump(&mut body, 60);

    let mut host = DropHost::new(&store);
    let item = host.carry(ObjectId(0x2883_0010));
    let creature = host.a_creature(ObjectId(0x2883_0011));
    let out = host.drop_onto(item, creature, Some(&body));
    let given = host.inter.player_on_ground() == Some(false)
        && out.len() == 1
        && is_give(&out[0])
        && host.lines().is_empty();

    c.assert_behaviour(
        "inventory.give.handing-something-over-in-mid-air-is-not-refused",
        { move |_| given },
    );
    c.shutdown();
}

/// Whether the player is on the ground is read again every frame, and not knowing is a value.
///
/// **A declared limit**: the call site that reads the body out of the rendered world needs a
/// device, so what is driven here is that the frame's own pass re-reads it at all and that a frame
/// with no world answers that it does not know. A change to *which* field of the body it reads
/// would not redden this, and nothing here claims otherwise.
pub fn the_ground_answer_is_read_again_every_frame() {
    let mut c = a_retail_client();
    let store = Arc::clone(c.dat_store().expect("a retail client opens the dats"));
    let body = a_settled_body(&store);
    let mut host = DropHost::new(&store);

    host.inter.note_player_physics(Some(&body));
    let told = host.inter.player_on_ground() == Some(true);
    let changed = host.inter.stats.physics_answers_changed;

    host.frame();
    let re_read = host.inter.player_on_ground().is_none()
        && host.inter.stats.physics_answers_changed == changed + 1;

    c.assert_behaviour(
        "inventory.world-drop.whether-the-player-is-on-the-ground-is-read-again-every-frame",
        move |_| told && re_read,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// f54: the shop's own latch.
// ---------------------------------------------------------------------------------------------

/// The recorded shopkeeper and the recorded player.
const SHOPKEEPER: ObjectId = ObjectId(0x77F0_3064);
const RECORDED_PLAYER: ObjectId = ObjectId(0x5000_000A);
/// The recording's own shop-opening message.
const SHOP_OPEN_AT: usize = 4736;
/// The shard's reply to the purchase, and to the sale.
const AFTER_THE_BUY_AT: usize = 4748;
const AFTER_THE_SALE_AT: usize = 4784;
/// The shop's buy button, its sell list and its sell-everything button.
const BTN_BUY: ElementId = ElementId(0x1000_00C2);
const SELL_LIST: ElementId = ElementId(0x1000_00CE);
const BTN_SELL_ALL: ElementId = ElementId(0x1000_00D3);
/// The page the backpack grid lives on, raised so that it holds live slots.
const INVENTORY_PAGE: ElementId = ElementId(0x1000_018B);

/// The recorded session, with the shop open and the backpack page up.
fn a_client_at_the_shop() -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    // The identity is chosen before the description arrives, and a replay with no login has no
    // step that carries it across.
    c.world_mut().player = Some(RECORDED_PLAYER);
    c.when(Inbound::from_corpus("long-solo-play", 0..SHOP_OPEN_AT + 1))
        .tick(4);

    let panel = {
        let app = c.app_mut();
        let shell = app.ui_mut().expect("the UI shell");
        let any: &mut dyn std::any::Any = &mut **shell.flow.current_mut().expect("a screen");
        let gp = any
            .downcast_mut::<GamePlayScreen>()
            .expect("the gameplay screen");
        let panel = gp
            .panels
            .pages
            .iter()
            .find(|p| p.element == INVENTORY_PAGE)
            .expect("the shipped inventory page")
            .panel_id;
        gp.recv_set_panel_visibility(&mut shell.ui, panel, true);
        panel
    };
    let _ = panel;
    c.tick(4);

    assert_eq!(
        c.view().world().shop.vendor_id,
        Some(SHOPKEEPER),
        "the premise: the recorded message names the shopkeeper"
    );
    assert!(
        c.view().expect_app().hud().panels.vendor.bound(),
        "the premise: the shop panel found its own lists"
    );
    c
}

fn element_of(c: &HeadlessClient, id: ElementId) -> ElemHandle {
    let app = c.view().expect_app();
    let shell = app.ui().expect("the UI shell");
    let any: &dyn std::any::Any = shell.flow.current().expect("a screen");
    let root = any
        .downcast_ref::<GamePlayScreen>()
        .expect("the gameplay screen")
        .root()
        .expect("the gameplay root");
    shell
        .ui
        .get_child_recursive(root, id)
        .unwrap_or_else(|| panic!("{id:?} is in the tree"))
}

/// Everything on the strip across the top of the screen, which is where the refusal is drawn and
/// what the player reads.
fn bubbles(c: &mut HeadlessClient) -> Vec<String> {
    let list = element_of(c, LIST_BOX);
    let shell = c.app_mut().ui_mut().expect("the UI shell");
    shell
        .ui
        .children(list)
        .into_iter()
        .filter_map(|h| {
            shell
                .ui
                .text_element_mut(h)
                .map(|t| t.glyphs.inq_text(false))
        })
        .collect()
}

/// Run frames and collect everything that reached the wire across them.
fn pump(c: &mut HeadlessClient) -> Vec<Request> {
    let mut sent = Vec::new();
    for _ in 0..4 {
        c.tick(1);
        sent.extend(
            c.view()
                .expect_app()
                .interaction()
                .last_sent
                .iter()
                .cloned(),
        );
    }
    sent
}

fn click(c: &mut HeadlessClient, id: ElementId) -> Vec<Request> {
    let h = element_of(c, id);
    c.app_mut()
        .ui_mut()
        .expect("the UI shell")
        .ui
        .broadcast_element_message(
            h,
            dereth_ui::msg::element::id::BUTTON_CLICKED,
            dereth_ui::focus::action::PRIMARY_CLICK,
            0,
        );
    pump(c)
}

fn press(c: &mut HeadlessClient, h: ElemHandle) {
    c.app_mut()
        .ui_mut()
        .expect("the UI shell")
        .ui
        .broadcast_element_message(
            h,
            dereth_ui::msg::element::id::MOUSE_PRESS,
            dereth_ui::focus::action::PRIMARY_CLICK,
            0,
        );
    let _ = pump(c);
}

/// The `(slot, object)` pairs the shop's own stock list is showing.
fn stock_slots(c: &HeadlessClient) -> Vec<(ElemHandle, ObjectId)> {
    c.view()
        .expect_app()
        .hud()
        .panels
        .vendor
        .stock
        .as_ref()
        .expect("the shop panel binds its stock list")
        .slots
        .iter()
        .filter_map(|s| s.item.map(|id| (s.handle, id)))
        .collect()
}

/// A live backpack slot holding something this shop would take.
fn sellable(c: &HeadlessClient) -> (ElemHandle, ObjectId) {
    let app = c.view().expect_app();
    let world = &app.objects().world;
    let any: &dyn std::any::Any = app
        .ui()
        .expect("the UI shell")
        .flow
        .current()
        .expect("a screen");
    any.downcast_ref::<GamePlayScreen>()
        .expect("the gameplay screen")
        .inventory
        .item_list
        .as_ref()
        .expect("the backpack grid is bound once the page is up")
        .slots
        .iter()
        .find_map(|s| {
            let id = s.item?;
            let w = world.weenie(id)?;
            (world.is_owned_by_player(id)
                && world.shop.profile.inq_acceptability(&w.pwd) == 0
                && world
                    .inventory(id)
                    .is_none_or(|i| i.items.is_empty() && i.containers.is_empty()))
            .then_some((s.handle, id))
        })
        .expect("the recorded pack shows at least one item this shop accepts")
}

/// The player's next action: a drag released on to their own pack, one of the gestures the
/// one-thing-at-a-time gate guards and the one that shows the sentence.
fn try_to_act(c: &mut HeadlessClient, item: ObjectId) -> Vec<Request> {
    c.app_mut().interaction_mut().queue(
        Vec::new(),
        vec![UiRequest::DragDrop {
            item,
            target: DropTarget::Container(RECORDED_PLAYER),
        }],
    );
    pump(c)
}

/// The bytes the one place a request becomes a datagram actually writes. Nothing is transmitted.
fn on_the_wire(r: &Request) -> Vec<u8> {
    let mut s = Session::new(MockTransport::new());
    assert!(
        dereth_client_runtime::requests::send_request(&mut s, r),
        "the sender has an arm for {r:?}"
    );
    s.transport.sent.last().expect("one blob").payload.clone()
}

fn dword(b: &[u8], n: usize) -> u32 {
    u32::from_le_bytes([b[n], b[n + 1], b[n + 2], b[n + 3]])
}

/// Whether the move the player wants really reached the wire, and the refusal is not on screen.
fn the_move_reached_the_wire(sent: &[Request], item: ObjectId, strip: &[String]) -> bool {
    if strip.iter().any(|b| b == BUSY) {
        return false;
    }
    let Some(m) = sent.iter().find_map(|r| match r {
        Request::PutItemInContainer(m) if m.item == item => Some(*m),
        _ => None,
    }) else {
        return false;
    };
    // …and the same request, encoded. A gate that answered success after parking the request
    // would satisfy the match above and produce nothing here.
    let b = on_the_wire(&Request::PutItemInContainer(m));
    m.container == RECORDED_PLAYER
        && dword(&b, 0) == 0xF7B1
        && dword(&b, 8) == 0x0019
        && ObjectId(dword(&b, 12)) == item
}

/// Buying and letting the shard answer leaves the player able to act.
pub fn a_purchase_leaves_the_player_able_to_act() {
    let mut c = a_client_at_the_shop();

    // The positive control: with nothing outstanding the same gesture goes through. Without it
    // every measurement below is about the wrong thing.
    let (_, item) = sellable(&c);
    let sent = try_to_act(&mut c, item);
    let strip = bubbles(&mut c);
    let control = the_move_reached_the_wire(&sent, item, &strip);
    assert!(
        control,
        "the premise: with nothing outstanding the player can act"
    );

    let mut c = a_client_at_the_shop();
    let (handle, stock) = *stock_slots(&c)
        .last()
        .expect("the live stock list holds a row");
    press(&mut c, handle);
    assert_eq!(
        c.view().world().selected,
        Some(stock),
        "the premise: the press picked the row"
    );

    let sent = click(&mut c, BTN_BUY);
    let buy = sent
        .iter()
        .find_map(|r| match r {
            Request::VendorBuy(m) if m.vendor_id == SHOPKEEPER => Some(m.clone()),
            _ => None,
        })
        .unwrap_or_else(|| panic!("the premise: the buy button puts a purchase on the wire"));
    let b = on_the_wire(&Request::VendorBuy(buy));
    let went_out =
        dword(&b, 0) == 0xF7B1 && dword(&b, 8) == 0x005F && ObjectId(dword(&b, 12)) == SHOPKEEPER;

    // The shard answers, with the recording's own datagram.
    c.when(Inbound::from_corpus(
        "long-solo-play",
        SHOP_OPEN_AT + 1..AFTER_THE_BUY_AT + 1,
    ))
    .tick(4);
    assert_eq!(
        c.view().world().shop.vendor_id,
        Some(SHOPKEEPER),
        "the premise: it is the same shopkeeper re-advertising itself"
    );

    let (_, item) = sellable(&c);
    let sent = try_to_act(&mut c, item);
    let strip = bubbles(&mut c);
    let free = the_move_reached_the_wire(&sent, item, &strip);

    c.assert_behaviour("vendor.busy.a-purchase-leaves-the-player-able-to-act", {
        move |_| control && went_out && free
    });
    c.shutdown();
}

/// Selling and letting the shard answer leaves the player able to act.
pub fn a_sale_leaves_the_player_able_to_act() {
    let mut c = a_client_at_the_shop();
    let (owner, offered) = sellable(&c);
    let target = element_of(&c, SELL_LIST);

    c.app_mut()
        .ui_mut()
        .expect("the UI shell")
        .ui
        .broadcast_element_message(
            target,
            dereth_ui::msg::element::id::DROP_FAILED,
            0,
            owner.raw(),
        );
    let _ = pump(&mut c);
    assert!(
        c.view()
            .world()
            .shop
            .sell_list
            .iter()
            .any(|(id, _)| *id == offered),
        "the premise: the item is in the sell basket"
    );

    let sent = click(&mut c, BTN_SELL_ALL);
    let sell = sent
        .iter()
        .find_map(|r| match r {
            Request::VendorSell(m) if m.vendor_id == SHOPKEEPER => Some(m.clone()),
            _ => None,
        })
        .unwrap_or_else(|| panic!("the premise: sell-everything puts a sale on the wire"));
    let b = on_the_wire(&Request::VendorSell(sell));
    let went_out =
        dword(&b, 0) == 0xF7B1 && dword(&b, 8) == 0x0060 && ObjectId(dword(&b, 12)) == SHOPKEEPER;

    c.when(Inbound::from_corpus(
        "long-solo-play",
        SHOP_OPEN_AT + 1..AFTER_THE_SALE_AT + 1,
    ))
    .tick(4);
    assert_eq!(c.view().world().shop.vendor_id, Some(SHOPKEEPER));

    let (_, item) = sellable(&c);
    let sent = try_to_act(&mut c, item);
    let strip = bubbles(&mut c);
    let free = the_move_reached_the_wire(&sent, item, &strip);

    c.assert_behaviour(
        "vendor.busy.a-sale-leaves-the-player-able-to-act",
        move |_| went_out && free,
    );
    c.shutdown();
}

/// While the shop really has not answered, the refusal still fires -- and a different merchant's
/// reply does not count as the answer.
///
/// **This is the point of the pair above**: a change that simply deleted the gate would pass both
/// of them and fail here.
pub fn while_the_shop_has_not_answered_the_refusal_still_fires() {
    let mut c = a_client_at_the_shop();
    let (handle, _) = *stock_slots(&c).last().expect("a filled row");
    press(&mut c, handle);
    assert!(
        !click(&mut c, BTN_BUY).is_empty(),
        "the premise: the buy went out"
    );

    let (_, item) = sellable(&c);
    let sent = try_to_act(&mut c, item);
    let refused = !sent
        .iter()
        .any(|r| matches!(r, Request::PutItemInContainer(_)))
        && bubbles(&mut c).iter().any(|b| b == BUSY);

    // The recorded reply, addressed to somebody else: the bytes are still the recording's.
    let mut row = Corpus::load("long-solo-play")
        .expect("the locked corpus decodes")
        .expect("long-solo-play is locked")
        .blobs
        .into_iter()
        .find(|r| r.idx == AFTER_THE_BUY_AT)
        .expect("the recorded reply to the purchase");
    row.payload[16..20].copy_from_slice(&0x77F0_9999_u32.to_le_bytes());
    c.when(Inbound::event(dereth_testkit::inbound::event_of(&row)))
        .tick(4);

    let (_, item) = sellable(&c);
    let sent = try_to_act(&mut c, item);
    let still_latched = !sent
        .iter()
        .any(|r| matches!(r, Request::PutItemInContainer(_)))
        && bubbles(&mut c).iter().any(|b| b == BUSY);

    c.assert_behaviour(
        "vendor.busy.while-the-shop-has-not-answered-the-refusal-still-fires",
        { move |_| refused && still_latched },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// The salvage window's drag-out.
// ---------------------------------------------------------------------------------------------

const SALVAGE_PLAYER: ObjectId = ObjectId(0x5000_0001);
const SALVAGE_TOOL: ObjectId = ObjectId(0x5000_0002);
const SALVAGE_RING: ObjectId = ObjectId(0x5000_0003);

fn seed_salvage(w: &mut dereth_client_model::World) {
    use dereth_client_model::weenie::item_type;

    w.set_player(SALVAGE_PLAYER);
    let mut me = dereth_client_model::Weenie::new(SALVAGE_PLAYER);
    me.valid = true;
    me.pwd.bitfield |= dereth_client_model::weenie::bitfield::PLAYER;
    me.pwd.items_capacity = Some(24);
    w.tables.weenies.insert(SALVAGE_PLAYER, me);

    let mut tool = dereth_client_model::Weenie::new(SALVAGE_TOOL);
    tool.valid = true;
    tool.pwd.name = "Iron Salvaging Kit".into();
    tool.pwd.icon_id = 0x0600_1234;
    tool.pwd.obj_type = item_type::TINKERING_TOOL;
    tool.pwd.container_id = Some(SALVAGE_PLAYER);
    w.tables.weenies.insert(SALVAGE_TOOL, tool);

    let mut ring = dereth_client_model::Weenie::new(SALVAGE_RING);
    ring.valid = true;
    ring.pwd.name = "Black Opal Ring".into();
    ring.pwd.icon_id = 0x0600_1234;
    ring.pwd.obj_type = item_type::JEWELRY;
    ring.pwd.material_type = Some(0x10);
    ring.pwd.structure = Some(40);
    ring.pwd.container_id = Some(SALVAGE_PLAYER);
    w.tables.weenies.insert(SALVAGE_RING, ring);

    w.tables.inventories.insert(
        SALVAGE_PLAYER,
        dereth_client_model::objects::ObjectInventory {
            container: ObjectId(0),
            items: vec![SALVAGE_TOOL, SALVAGE_RING],
            containers: Vec::new(),
            placements: Vec::new(),
        },
    );
}

fn gameplay_screen(app: &mut App) -> (&mut UiSystem, &mut GamePlayScreen) {
    let shell = app.ui_mut().expect("the UI shell is up");
    let ui = &mut shell.ui;
    let screen = shell.flow.current_mut().expect("a current screen");
    let any: &mut dyn std::any::Any = &mut **screen;
    (
        ui,
        any.downcast_mut::<GamePlayScreen>()
            .expect("the gameplay screen"),
    )
}

fn centre(ui: &UiSystem, h: ElemHandle) -> (i32, i32) {
    let (ox, oy) = ui.screen_origin(h);
    let b = ui.node(h).expect("alive").region.box_;
    (ox + b.width() / 2, oy + b.height() / 2)
}

fn pack_slot(c: &mut HeadlessClient, item: ObjectId) -> ElemHandle {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .item_list
        .as_ref()
        .expect("the pack grid")
        .slots
        .iter()
        .find(|slot| slot.item == Some(item))
        .unwrap_or_else(|| panic!("{item:?} has no pack tile"))
        .handle
}

fn salvage_tile(c: &HeadlessClient) -> ElemHandle {
    c.view()
        .expect_app()
        .hud()
        .panels
        .salvage
        .list
        .as_ref()
        .expect("the salvage list is bound")
        .slots
        .first()
        .expect("the salvage list has a row")
        .handle
}

fn open_pack(c: &mut HeadlessClient) {
    let panel_id = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        screen
            .panels
            .pages
            .iter()
            .find(|page| page.element == INVENTORY_PAGE)
            .map(|page| page.panel_id)
            .expect("the inventory page is present")
    };
    let (ui, screen) = gameplay_screen(c.app_mut());
    screen.recv_set_panel_visibility(ui, panel_id, true);
    c.tick(2);
}

fn use_the_tool(c: &mut HeadlessClient) {
    let tile = pack_slot(c, SALVAGE_TOOL);
    let (ui, _screen) = gameplay_screen(c.app_mut());
    let (x, y) = centre(ui, tile);
    ui.mouse_move(dereth_primitives::LocalTime(1.0), x, y);
    ui.mouse_down(0x0A, x, y);
    c.tick(3);
}

fn pick_up(c: &mut HeadlessClient, tile: ElemHandle, t: f64) {
    let (ui, _screen) = gameplay_screen(c.app_mut());
    let (x, y) = centre(ui, tile);
    ui.mouse_move(dereth_primitives::LocalTime(t), x, y);
    ui.mouse_down(dereth_ui::focus::action::PRIMARY_CLICK, x, y);
    ui.mouse_move(dereth_primitives::LocalTime(t + 0.05), x + 8, y + 8);
    c.tick(1);
}

fn put_the_ring_in(c: &mut HeadlessClient) {
    let from = pack_slot(c, SALVAGE_RING);
    let root = gameplay_screen(c.app_mut()).1.root().expect("a root");
    let to = gameplay_screen(c.app_mut())
        .0
        .get_child_recursive(root, salvage::LIST)
        .expect("the salvage list is in the shipped tree");
    pick_up(c, from, 2.0);
    let (ui, _screen) = gameplay_screen(c.app_mut());
    let (x, y) = centre(ui, to);
    ui.mouse_move(dereth_primitives::LocalTime(2.1), x, y);
    c.tick(1);
    let (ui, _screen) = gameplay_screen(c.app_mut());
    ui.mouse_up(dereth_ui::focus::action::PRIMARY_CLICK, x, y, false);
    c.tick(2);
    assert_eq!(
        c.view().expect_app().hud().panels.salvage.displayed,
        vec![SALVAGE_RING],
        "the premise: the ring is in the salvage window"
    );
}

/// A client with the salvage window open and one row in it.
fn a_client_with_a_salvage_row() -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay_in_world(4));
    seed_salvage(&mut c.app_mut().objects_mut().world);
    open_pack(&mut c);
    use_the_tool(&mut c);
    put_the_ring_in(&mut c);
    c
}

/// A row dragged out of the salvage window comes off it, and a click does not.
pub fn a_salvage_row_dragged_out_leaves_the_list() {
    let mut c = a_client_with_a_salvage_row();

    let tile = salvage_tile(&c);
    let (ui, _screen) = gameplay_screen(c.app_mut());
    let (x, y) = centre(ui, tile);
    ui.mouse_move(dereth_primitives::LocalTime(3.0), x, y);
    ui.mouse_down(dereth_ui::focus::action::PRIMARY_CLICK, x, y);
    ui.mouse_up(dereth_ui::focus::action::PRIMARY_CLICK, x, y, false);
    c.tick(1);
    let a_click_is_not_a_drag =
        c.view().expect_app().hud().panels.salvage.displayed == vec![SALVAGE_RING];

    let tile = salvage_tile(&c);
    pick_up(&mut c, tile, 4.0);
    let (item, flags) = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let proxy = ui
            .drag_state()
            .element
            .expect("the salvage row started a drag");
        let info = inq_drop_icon_info(ui, proxy);
        (info.item, info.flags)
    };
    let button = c
        .view()
        .expect_app()
        .hud()
        .panels
        .salvage
        .salvage_button
        .expect("bound");
    let button_state = gameplay_screen(c.app_mut())
        .0
        .node(button)
        .expect("alive")
        .state;
    let app = c.view().expect_app();
    let taken_off = item == Some(SALVAGE_RING)
        && flags & drag_flags::IS_SALVAGE == drag_flags::IS_SALVAGE
        && app.hud().panels.salvage.displayed.is_empty()
        && app.hud().panels.salvage.items_removed == 1
        && app.hud().panels.salvage.button == SalvageButton::Disabled
        && button_state == dereth_ui::StateId(0x0D)
        && app.interaction().last_sent.is_empty();

    c.assert_behaviour(
        "salvage.row.dragging-one-out-takes-it-off-the-list-and-sends-nothing",
        { move |_| a_click_is_not_a_drag && taken_off },
    );
    c.shutdown();
}

/// A refused drag naming the whole list starts nothing and removes nothing.
pub fn a_refusal_naming_the_list_starts_nothing() {
    let mut c = a_client_with_a_salvage_row();
    let slot = salvage_tile(&c);
    let list = c
        .view()
        .expect_app()
        .hud()
        .panels
        .salvage
        .list
        .as_ref()
        .expect("the salvage list is bound")
        .handle;

    {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let (x, y) = centre(ui, slot);
        let (ox, oy) = ui.screen_origin(list);
        let point = dereth_ui::msg::element::MessagePoint {
            window: (x, y),
            element: (x - ox, y - oy),
        };
        ui.broadcast_element_message_at(
            list,
            dereth_ui::msg::element::id::DRAG_REJECTED,
            0,
            0,
            point,
        );
    }
    c.tick(1);

    let app = c.view().expect_app();
    let untouched = app.hud().panels.salvage.displayed == vec![SALVAGE_RING]
        && app.hud().panels.salvage.items_removed == 0;
    let no_drag = gameplay_screen(c.app_mut())
        .0
        .drag_state()
        .element
        .is_none();

    c.assert_behaviour(
        "salvage.row.a-message-naming-the-whole-list-starts-no-drag",
        { move |_| untouched && no_drag },
    );
    c.shutdown();
}

/// A drag the shell refuses still takes the row off, and letting go does not put it back.
///
/// The premise is asserted first: the row the shipped screen actually ships **cannot** reach that
/// refusal, which is why the scenario has to force it and why forcing it is not inventing a state
/// the client could not be in from the other direction.
pub fn a_refused_drag_still_takes_the_salvage_row_off() {
    let mut c = a_client_with_a_salvage_row();

    {
        let slot = salvage_tile(&c);
        let icon = c
            .view()
            .expect_app()
            .hud()
            .panels
            .salvage
            .list
            .as_ref()
            .expect("bound")
            .slots
            .first()
            .expect("a row")
            .drag_icon
            .expect("the row has a drag icon");
        let (ui, _screen) = gameplay_screen(c.app_mut());
        assert!(
            ui.node(icon).expect("alive").flags.dragable(),
            "the premise: the shipped drag icon is draggable, so the shell accepts it"
        );
        assert_eq!(
            ui.node(slot)
                .expect("alive")
                .merged_properties()
                .get_bool(dereth_ui::props::attr::NO_DRAG_PROXY),
            Some(false),
            "the premise: the shipped row does not forbid the proxy"
        );
    }

    let slot = salvage_tile(&c);
    {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        ui.set_attribute_bool(slot, dereth_ui::props::attr::NO_DRAG_PROXY, true);
    }
    let slot = salvage_tile(&c);
    pick_up(&mut c, slot, 4.0);

    let nothing_on_the_cursor = gameplay_screen(c.app_mut())
        .0
        .drag_state()
        .element
        .is_none();
    let app = c.view().expect_app();
    let gone = app.hud().panels.salvage.displayed.is_empty()
        && app.hud().panels.salvage.items_removed == 1
        && app.hud().panels.salvage.button == SalvageButton::Disabled
        && app.interaction().last_sent.is_empty();

    {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        ui.mouse_up(dereth_ui::focus::action::PRIMARY_CLICK, 10, 10, false);
    }
    c.tick(1);
    let stays_gone = c
        .view()
        .expect_app()
        .hud()
        .panels
        .salvage
        .displayed
        .is_empty();

    c.assert_behaviour(
        "salvage.row.a-drag-the-shell-refuses-still-takes-the-row-off-and-letting-go-does-not-put-it-back",
        move |_| nothing_on_the_cursor && gone && stays_gone,
    );
    c.shutdown();
}

