// =============================================================================================
// The drag: picking an icon up out of the pack and letting it go somewhere.
//
// These are written on `Player::Drag`, so the first thing they rest on is that the step's motion
// satisfies the shell's own drag threshold.
//
// **It does, and here is what the threshold is.** `UiSystem::mouse_move` arms a pending drag on
// the press and starts it only once `dx^2 + dy^2 > 15` -- about four pixels from the press
// point. `Player::Drag` delivers its motion in two moves rather than one, and the first of them
// is the midpoint between the two targets, so a drag between two live elements passes the
// threshold on the first move and arrives on the second. A single-move implementation would
// have passed here too, since the arrival point is also far from the origin; what actually
// makes the step work is that each move is delivered **while the button is down** and is
// followed by a frame, because the shell reads the pointer out of the input manager once per
// frame and a second move delivered before that frame would replace the first.
//
// What `Player::Drag` cannot do is say anything about the screen *between* the press and the
// release, which is what most of the scenarios below are about. Those are driven through
// `dereth_testkit::adapters_inventory`, the same gesture in three steps.
// =============================================================================================

use dereth_testkit::adapters_inventory::{Grab, Over, Release};
use dereth_testkit::{ScreenPoint, Target};

const DRAG_PLAYER: ObjectId = ObjectId(0x5000_0011);
const DRAG_ITEM: ObjectId = ObjectId(0x5000_0012);
const DRAG_PACK: ObjectId = ObjectId(0x5000_0013);
/// A surface id nothing else in this file is drawing, so a picture that matches it came from
/// this item and from nowhere else.
const DRAG_ICON: DataId = DataId(0x0600_1234);

/// A player carrying one loose item and one side pack, and nothing else.
fn seed_a_pack(w: &mut dereth_client_model::World) {
    use dereth_client_model::weenie::{bitfield, item_type};

    w.set_player(DRAG_PLAYER);
    let mut me = dereth_client_model::Weenie::new(DRAG_PLAYER);
    me.valid = true;
    me.pwd.bitfield |= bitfield::PLAYER | bitfield::OPENABLE;
    me.pwd.items_capacity = Some(24);
    me.pwd.containers_capacity = Some(7);
    w.tables.weenies.insert(DRAG_PLAYER, me);

    let mut item = dereth_client_model::Weenie::new(DRAG_ITEM);
    item.valid = true;
    item.pwd.name = "Black Opal Ring".into();
    item.pwd.icon_id = DRAG_ICON.0;
    item.pwd.obj_type = item_type::JEWELRY;
    item.pwd.container_id = Some(DRAG_PLAYER);
    w.tables.weenies.insert(DRAG_ITEM, item);

    let mut pack = dereth_client_model::Weenie::new(DRAG_PACK);
    pack.valid = true;
    pack.pwd.name = "Backpack".into();
    pack.pwd.icon_id = 0x0600_1235;
    pack.pwd.obj_type = item_type::CONTAINER;
    pack.pwd.bitfield |= bitfield::OPENABLE;
    pack.pwd.items_capacity = Some(24);
    pack.pwd.container_id = Some(DRAG_PLAYER);
    w.tables.weenies.insert(DRAG_PACK, pack);

    w.tables.inventories.insert(
        DRAG_PLAYER,
        dereth_client_model::objects::ObjectInventory {
            container: ObjectId(0),
            items: vec![DRAG_ITEM],
            containers: vec![DRAG_PACK],
            placements: Vec::new(),
        },
    );
    w.tables.inventories.insert(
        DRAG_PACK,
        dereth_client_model::objects::ObjectInventory::new(DRAG_PACK),
    );
}

/// A whole client, with the pack page up, one loose item in the grid and one side pack on the
/// strip.
fn a_client_with_a_loose_item_and_a_side_pack() -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    seed_a_pack(&mut c.app_mut().objects_mut().world);
    open_pack(&mut c);
    c.tick(2);
    c
}

/// The strip slot a side pack is drawn in.
fn strip_slot(c: &mut HeadlessClient, item: ObjectId) -> ElemHandle {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .container_list
        .as_ref()
        .expect("the side-pack strip is bound")
        .slots
        .iter()
        .find(|s| s.item == Some(item))
        .unwrap_or_else(|| panic!("{item:?} is not on the side-pack strip"))
        .handle
}

/// Where a live element is, as a pointer target.
///
/// A pack slot cannot be named by its element id: the grid builds a hundred of them from one
/// template, so every slot carries the same shipped id and `Target::Element` would always answer
/// the first. The point is the slot's own centre.
fn point_of(c: &mut HeadlessClient, h: ElemHandle) -> Target {
    let (ui, _screen) = gameplay_screen(c.app_mut());
    let (x, y) = centre(ui, h);
    Target::Point(ScreenPoint::new(x, y))
}

// ---------------------------------------------------------------------------------------------
// inventory.drag.a-pack-slot-answers-the-pointer-at-its-own-centre
// ---------------------------------------------------------------------------------------------

/// Every slot the grid shows answers a pointer at its own centre.
///
/// The claim is about the slots the list **shows**: the grid is laid out with more cells than
/// its own box holds, and the ones below it are not hit-testable and must not be, because a cell
/// outside the list is outside the panel too. So the walk splits them and asserts over the
/// on-screen half, having first required that half to be at least two rows -- otherwise an empty
/// answer would score as a pass.
pub fn a_pack_slot_answers_the_pointer_at_its_own_centre() {
    let mut c = a_client_with_a_loose_item_and_a_side_pack();

    let (probes, shown, every_slot_can_be_lifted_from) = {
        let (ui, screen) = gameplay_screen(c.app_mut());
        let grid = screen
            .inventory
            .item_list
            .as_ref()
            .expect("the pack grid is bound");
        let list_box = ui.node(grid.handle).expect("alive").region.box_;
        let handles: Vec<(ElemHandle, bool, bool)> = grid
            .slots
            .iter()
            .map(|s| {
                let n = ui.node(s.handle).expect("alive");
                (s.handle, n.is_mouse_visible, s.drag_icon.is_some())
            })
            .collect();
        let shown = handles.len();
        let mut liftable = true;
        let mut probes = Vec::new();
        for (h, mouse_visible, has_drag_icon) in handles {
            liftable &= mouse_visible && has_drag_icon;
            let b = ui.node(h).expect("alive").region.box_;
            let (cx, cy) = (b.x0 + b.width() / 2, b.y0 + b.height() / 2);
            if cx >= 0 && cy >= 0 && cx < list_box.width() && cy < list_box.height() {
                probes.push((h, centre(ui, h)));
            }
        }
        (probes, shown, liftable)
    };
    assert!(shown > 1, "the premise: the grid has slots at all");
    assert!(
        probes.len() >= 12,
        "the premise: at least two rows of six are on screen"
    );

    let (ui, _screen) = gameplay_screen(c.app_mut());
    let answered = probes
        .iter()
        .filter(|(h, (x, y))| ui.hit_test_screen(*x, *y) == Some(*h))
        .count();
    let all_of_them = answered == probes.len();

    c.assert_behaviour(
        "inventory.drag.a-pack-slot-answers-the-pointer-at-its-own-centre",
        { move |_| all_of_them && every_slot_can_be_lifted_from },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag.a-press-and-a-move-lift-the-items-own-picture-off-its-slot
// ---------------------------------------------------------------------------------------------

/// A press and a move lift a copy of what the slot is drawing, and the slot greys behind it.
///
/// Driven in three steps rather than through `Player::Drag`, because every assertion here is
/// about the state the client is in **while** the icon is in the air: after a release there is
/// no proxy left to read.
pub fn a_press_and_a_move_lift_the_items_own_picture() {
    let mut c = a_client_with_a_loose_item_and_a_side_pack();
    let slot = pack_slot(&mut c, DRAG_ITEM);
    let drawn = {
        let (ui, screen) = gameplay_screen(c.app_mut());
        let grid = screen.inventory.item_list.as_ref().expect("the grid");
        let s = grid
            .slots
            .iter()
            .find(|s| s.handle == slot)
            .expect("the slot");
        let icon = s.icon.expect("the slot's own picture element");
        ui.node(icon).expect("alive").region.image.clone()
    };
    assert!(
        drawn.is_some(),
        "the premise: the slot is drawing the item's picture"
    );

    let from = point_of(&mut c, slot);
    c.when(Grab(from));

    let (carried, is_a_plain_move, picture, was) = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let proxy = ui
            .drag_state()
            .element
            .expect("the press and the move made no drag proxy");
        let info = inq_drop_icon_info(ui, proxy);
        let picture = ui.node(proxy).expect("alive").region.image.clone();
        let box_ = ui.node(proxy).expect("alive").region.box_;
        (info.item, info.is_inventory_move(), picture, box_)
    };
    // **The copy is not byte-identical to the slot, and the row says so.** What the slot draws
    // is the item's picture *inside the slot's own frame*; what is lifted is the picture with
    // the frame left behind, which is what a player sees follow the cursor. So the claim is over
    // the surface each of them names, which is the item's own and nothing else's.
    let surface_of = |g: &Option<dereth_ui::GraphicRef>| {
        g.as_ref().map(|g| {
            let icon = match g.op.and_then(|op| op.icon_recipe()) {
                Some(dereth_ui::region::IconRecipe::Object { icon, .. }) => icon,
                _ => None,
            };
            (g.did, icon)
        })
    };
    let the_items_own_picture = surface_of(&picture) == Some((DRAG_ICON, Some(DRAG_ICON)))
        && surface_of(&drawn) == surface_of(&picture);

    // The copy follows the pointer.
    let elsewhere = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let (x, y) = ui.mouse_pos();
        Target::Point(ScreenPoint::new(x + 60, y + 40))
    };
    c.when(Over(elsewhere));
    let moved = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let proxy = ui.drag_state().element.expect("still in the air");
        ui.node(proxy).expect("alive").region.box_ != was
    };

    let (greyed, still_where_it_was) = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        let s = screen
            .inventory
            .item_list
            .as_ref()
            .expect("the grid")
            .slots
            .iter()
            .find(|s| s.handle == slot)
            .expect("still there");
        (s.waiting, s.item == Some(DRAG_ITEM))
    };
    let unmoved = c
        .app_mut()
        .objects()
        .world
        .weenie(DRAG_ITEM)
        .expect("seeded")
        .pwd
        .container_id
        == Some(DRAG_PLAYER);
    c.when(Release);

    c.assert_behaviour(
        "inventory.drag.a-press-and-a-move-lift-the-items-own-picture-off-its-slot",
        move |_| {
            carried == Some(DRAG_ITEM)
                && is_a_plain_move
                && the_items_own_picture
                && moved
                && greyed
                && still_where_it_was
                && unmoved
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag.a-drop-on-a-side-pack-becomes-one-move-naming-the-pack-under-the-pointer
// ---------------------------------------------------------------------------------------------

/// **The `Player::Drag` proof.** One whole-gesture step from the grid to the side-pack strip
/// becomes exactly one move, naming the pack and the place in the strip it landed on.
///
/// The second half drives the two links the pointer cannot reach from here -- the request being
/// turned into the shard message, and the shard's own answer moving the item -- on the client's
/// own world, with the ids the drag itself produced.
pub fn a_drop_on_a_side_pack_becomes_one_move() {
    let mut c = a_client_with_a_loose_item_and_a_side_pack();
    let source = pack_slot(&mut c, DRAG_ITEM);
    let target = strip_slot(&mut c, DRAG_PACK);
    let (from, to) = (point_of(&mut c, source), point_of(&mut c, target));
    clear_requests(c.ui_outbox());

    c.when(Player::Drag {
        from,
        to,
        hold_frames: 1,
    });

    // **Nothing is left in the screen's own outbox to read.** The frames `Player::Drag` runs
    // after the release are the frames that dispatch the drop, and `App::frame` drains that
    // outbox into the interaction layer inside them -- so the `DropTarget` shape the drop
    // resolved to is gone by the time a scenario can look, and what is asserted instead is the
    // request the client actually sent and the slot the panel resolves. The receipt ranks that
    // as a harness gap; it is not a weakening of this row, whose claim is the move.
    let nothing_left_over = take_requests(c.ui_outbox()).is_empty();

    // The strip slot the pointer landed on resolves, through the panel's own map, to the pack --
    // dropping into the wrong container is the invisible-wrong case this tier exists for.
    let resolves_to_the_pack = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        let (list, slot, at) = screen
            .inventory
            .locate(target)
            .expect("a slot the panel knows");
        at == Some(DRAG_PACK)
            && screen
                .inventory
                .resolve_drop(DropTarget::ItemList { list, slot })
                == Some(DRAG_PACK)
    };

    // **The drag has already been routed**, which is the point: the frames `Player::Drag` runs
    // after the release hand the drop to the client's own interaction layer, and what that layer
    // sent is what a shard would have received. Re-driving the move by hand here is refused for
    // the right reason -- the one-item-at-a-time lock the drag itself took -- so the request is
    // read off the client rather than made again.
    let sent: Vec<_> = c
        .outbound()
        .iter()
        .filter_map(|r| match r {
            Request::PutItemInContainer(m) => Some((m.item, m.container)),
            _ => None,
        })
        .collect();
    let one_message = sent.len() == 1;
    let names_them = sent.first() == Some(&(DRAG_ITEM, DRAG_PACK));

    // Until the shard answers, the client predicts nothing and holds the slot greyed.
    let (ghosted, not_yet_moved) = {
        let w = &c.app_mut().objects().world;
        let we = w.weenie(DRAG_ITEM).expect("seeded");
        (we.waiting, we.pwd.container_id == Some(DRAG_PLAYER))
    };
    let (moved_by_the_shard, grey_cleared) = {
        let w = &mut c.app_mut().objects_mut().world;
        w.server_says_move_item(
            DRAG_ITEM,
            DRAG_PACK,
            0,
            ObjectId(0),
            0,
            true,
            &mut dereth_client_model::NullSink,
        );
        let we = w.weenie(DRAG_ITEM).expect("still there");
        (we.pwd.container_id == Some(DRAG_PACK), !we.waiting)
    };
    c.assert_behaviour(
        "inventory.drag.a-drop-on-a-side-pack-becomes-one-move-naming-the-pack-under-the-pointer",
        move |_| {
            nothing_left_over
                && resolves_to_the_pack
                && one_message
                && names_them
                && ghosted
                && not_yet_moved
                && moved_by_the_shard
                && grey_cleared
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag.an-empty-slot-starts-nothing-and-a-list-that-forbids-it-starts-nothing
// ---------------------------------------------------------------------------------------------

/// The two gates that decide whether a slot can be picked up at all.
pub fn an_empty_slot_and_a_forbidden_list_start_nothing() {
    let mut c = a_client_with_a_loose_item_and_a_side_pack();

    let empty = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        let grid = screen.inventory.item_list.as_ref().expect("the grid");
        assert!(
            grid.allow_dragging,
            "the premise: the pack grid may be dragged from"
        );
        grid.slots
            .iter()
            .find(|s| s.item.is_none())
            .expect("an empty slot")
            .handle
    };
    let at_the_empty_slot = point_of(&mut c, empty);
    c.when(Grab(at_the_empty_slot));
    let nothing_was_lifted = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        ui.drag_state().element.is_none()
    };
    c.when(Release);
    let left_clean = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        !ui.drag_state().started
    };

    // The `AllowDragging` gate itself, over a filled slot, off and on.
    let filled = pack_slot(&mut c, DRAG_ITEM);
    let (refused_without_it, allowed_with_it) = {
        let (ui, screen) = gameplay_screen(c.app_mut());
        let (x, y) = centre(ui, filled);
        let grid: &mut ItemListWidget = screen.inventory.item_list.as_mut().expect("the grid");
        grid.allow_dragging = false;
        let refused = grid.begin_drag(ui, x, y).is_none();
        grid.allow_dragging = true;
        let allowed = grid.begin_drag(ui, x, y).is_some();
        (refused, allowed)
    };

    c.assert_behaviour(
        "inventory.drag.an-empty-slot-starts-nothing-and-a-list-that-forbids-it-starts-nothing",
        move |_| nothing_was_lifted && left_clean && refused_without_it && allowed_with_it,
    );
    c.shutdown();
}

#[test]
fn scenario_a_pack_slot_answers_the_pointer_at_its_own_centre() {
    scenario("a_pack_slot_answers_the_pointer_at_its_own_centre");
}

#[test]
fn scenario_a_press_and_a_move_lift_the_items_own_picture() {
    scenario("a_press_and_a_move_lift_the_items_own_picture");
}

#[test]
fn scenario_a_drop_on_a_side_pack_becomes_one_move() {
    scenario("a_drop_on_a_side_pack_becomes_one_move");
}

#[test]
fn scenario_an_empty_slot_and_a_forbidden_list_start_nothing() {
    scenario("an_empty_slot_and_a_forbidden_list_start_nothing");
}

// =============================================================================================
// The hints a drag lights on what it is carried over.
//
// Three targets that are not ordinary item lists -- the toolbar's backpack button, the paper
// doll's body slots and the shortcut bar -- plus the hint coming down on a drop, and the sentence
// the client says when a worn thing is dropped back where it already is.
//
// Every hint is read off the live element the pointer hit-tested to, and every gesture is
// `Grab` / `Over` / `Drop`, so a hint that lit because a scenario raised a message by hand could
// not pass. Each scenario asserts its premise before it measures: the element under the pointer
// must be the one that catches this drag.
// =============================================================================================

use dereth_testkit::adapters_inventory::Drop as LetGo;
use dereth_ui::StateId;
use dereth_ui_screens::items::widget::drag_accept_state;
use dereth_ui_screens::toolbar::{INVENTORY_BUTTON, INVENTORY_DRAG_OVERLAY};

/// The lit state of the backpack button's own overlay.
const OVERLAY_DRAG_OVER: StateId = StateId(0x1000_0046);
/// Its resting state.
const OVERLAY_NONE: StateId = StateId(0x1000_003F);

const DOLL_WEAPON_SLOT: ElementId = ElementId(0x1000_01DF);
const DOLL_SHIELD_SLOT: ElementId = ElementId(0x1000_01E1);
const DOLL_SHIRT_SLOT: ElementId = ElementId(0x1000_01E2);

const HINT_PLAYER: ObjectId = ObjectId(0x5000_0001);
const SHIELD: ObjectId = ObjectId(0x5000_0010);
const SWORD: ObjectId = ObjectId(0x5000_0011);
const TORCH: ObjectId = ObjectId(0x5000_0012);
const PLAIN_ROCK: ObjectId = ObjectId(0x5000_0013);
const SHIRT: ObjectId = ObjectId(0x5000_0014);
const HINT_ITEMS: [ObjectId; 4] = [SHIELD, SWORD, TORCH, PLAIN_ROCK];

/// A player carrying a shield, a one-handed sword, a torch and a rock. The first three can each
/// go in a different place on the body and the rock can go nowhere, which is what makes the
/// body-slot claim a claim rather than a constant.
fn seed_for_hints(w: &mut dereth_client_model::World) {
    use dereth_client_model::inventory::slots::loc;

    w.player = Some(HINT_PLAYER);
    w.tables.inventories.insert(
        HINT_PLAYER,
        dereth_client_model::objects::ObjectInventory::new(HINT_PLAYER),
    );
    for id in HINT_ITEMS.iter().copied().chain([HINT_PLAYER]) {
        let mut wn = dereth_client_model::Weenie::new(id);
        wn.valid = true;
        wn.pwd.name = format!("obj{:X}", id.0 & 0xFF);
        w.tables.weenies.insert(id, wn);
    }
    {
        let p = w.tables.weenies.get_mut(HINT_PLAYER).expect("seeded");
        p.pwd.items_capacity = Some(102);
        p.pwd.containers_capacity = Some(7);
        p.pwd.bitfield |= dereth_client_model::weenie::bitfield::OPENABLE;
    }
    for (id, mask) in [
        (SHIELD, loc::SHIELD),
        (SWORD, loc::MELEE_WEAPON),
        (TORCH, loc::HELD),
    ] {
        w.tables
            .weenies
            .get_mut(id)
            .expect("seeded")
            .pwd
            .valid_locations = Some(mask);
    }
    for (i, id) in HINT_ITEMS.iter().enumerate() {
        w.tables
            .weenies
            .get_mut(*id)
            .expect("seeded")
            .pwd
            .container_id = Some(HINT_PLAYER);
        w.tables
            .inventories
            .get_mut(HINT_PLAYER)
            .expect("seeded")
            .add_content(*id, false, i);
    }
}

fn a_client_with_four_things() -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay_in_world(4));
    seed_for_hints(&mut c.app_mut().objects_mut().world);
    open_pack(&mut c);
    c.tick(2);
    c
}

/// A shipped element of the gameplay screen, by id.
fn shipped(c: &mut HeadlessClient, id: ElementId) -> ElemHandle {
    let (ui, root) = gameplay_root(c.app_mut());
    ui.get_child_recursive(root, id)
        .unwrap_or_else(|| panic!("{id:?} is in the shipped tree"))
}

/// The state the backpack button's own overlay is in.
fn backpack_overlay(c: &mut HeadlessClient) -> StateId {
    let h = shipped(c, INVENTORY_DRAG_OVERLAY);
    let (ui, _root) = gameplay_root(c.app_mut());
    ui.node(h).expect("alive").state
}

/// One body slot's tile.
fn doll_tile(c: &mut HeadlessClient, element: ElementId) -> ElemHandle {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .doll
        .iter()
        .find(|(_, w)| w.element == element)
        .unwrap_or_else(|| panic!("the body slot {element:?} is bound"))
        .1
        .slots[0]
        .handle
}

/// The hint one body slot is showing.
fn doll_hint(c: &mut HeadlessClient, element: ElementId) -> Option<StateId> {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .doll
        .iter()
        .find(|(_, w)| w.element == element)
        .unwrap_or_else(|| panic!("the body slot {element:?} is bound"))
        .1
        .slots[0]
        .drag_accept_state
}

/// What the body slot is holding.
fn doll_item(c: &mut HeadlessClient, element: ElementId) -> Option<ObjectId> {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .doll
        .iter()
        .find(|(_, w)| w.element == element)
        .unwrap_or_else(|| panic!("the body slot {element:?} is bound"))
        .1
        .item_at(0)
}

fn shortcut_tile(c: &mut HeadlessClient, n: usize) -> ElemHandle {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .shortcuts
        .slots
        .get(n)
        .expect("the shortcut list is bound")
        .slots[0]
        .handle
}

fn shortcut_hint(c: &mut HeadlessClient, n: usize) -> Option<StateId> {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen.shortcuts.slots[n].slots[0].drag_accept_state
}

/// The state the shortcut tile's own hint element is in -- the element, not the panel's record.
fn shortcut_overlay(c: &mut HeadlessClient, n: usize) -> StateId {
    let h = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        screen.shortcuts.slots[n].slots[0]
            .drag_accept
            .expect("the tile's hint overlay is bound")
    };
    let (ui, _root) = gameplay_root(c.app_mut());
    ui.node(h).expect("alive").state
}

/// Carry the drag over `to`, having first required that the pointer really is over it: the
/// element the hit test finds must be the one that catches this drag, or the hint read next was
/// raised on something else.
fn carry_over(c: &mut HeadlessClient, to: ElemHandle) -> Target {
    let (x, y) = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        centre(ui, to)
    };
    let at = Target::Point(ScreenPoint::new(x, y));
    c.when(Over(at));
    {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let hit = ui
            .hit_test_screen(x, y)
            .expect("the pointer is over something");
        assert!(
            ui.drag_and_drop_catcher(hit) == Some(to) || ui.is_ancestor_of(to, hit),
            "the premise: the element under the pointer catches this drag"
        );
    }
    at
}

/// The text of every line the notice strip is showing.
fn strip_lines(c: &mut HeadlessClient) -> Vec<String> {
    let list = shipped(c, LIST_BOX);
    let (ui, _root) = gameplay_root(c.app_mut());
    ui.children(list)
        .into_iter()
        .filter_map(|h| ui.text_element_mut(h).map(|t| t.glyphs.inq_text(false)))
        .collect()
}

// ---------------------------------------------------------------------------------------------
// inventory.drag-hint.the-backpack-button-lights-while-something-is-carried-over-it
// ---------------------------------------------------------------------------------------------

/// The big backpack button on the toolbar lights while something is held over it, and goes dark
/// again the moment the pointer leaves.
pub fn the_backpack_button_lights_while_something_is_over_it() {
    let mut c = a_client_with_four_things();
    // The control. Nothing has written this element yet, so it is in no state at all -- which is
    // not the lit one, which is all the measurement below needs of it.
    let resting = backpack_overlay(&mut c);

    let button = shipped(&mut c, INVENTORY_BUTTON);
    let rock = pack_slot(&mut c, PLAIN_ROCK);
    let from = point_of(&mut c, rock);
    c.when(Grab(from));
    carry_over(&mut c, button);
    let lit = backpack_overlay(&mut c) == OVERLAY_DRAG_OVER;

    let torch = pack_slot(&mut c, TORCH);
    let at = carry_over(&mut c, torch);
    let dark_again = backpack_overlay(&mut c) == OVERLAY_NONE;
    c.when(LetGo(at));
    clear_requests(c.ui_outbox());

    c.assert_behaviour(
        "inventory.drag-hint.the-backpack-button-lights-while-something-is-carried-over-it",
        move |_| resting != OVERLAY_DRAG_OVER && lit && dark_again,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag-hint.a-body-slot-shows-whether-it-could-take-what-is-carried
// ---------------------------------------------------------------------------------------------

/// Carry `item` over `over` and report what both the shield slot and the weapon slot say about
/// it, then let go where the pointer is so the next station starts clean.
fn hints_while_carrying(
    c: &mut HeadlessClient,
    item: ObjectId,
    over: ElemHandle,
) -> (Option<StateId>, Option<StateId>) {
    let tile = pack_slot(c, item);
    let from = point_of(c, tile);
    c.when(Grab(from));
    let at = carry_over(c, over);
    let both = (
        doll_hint(c, DOLL_SHIELD_SLOT),
        doll_hint(c, DOLL_WEAPON_SLOT),
    );
    c.when(LetGo(at));
    clear_requests(c.ui_outbox());
    both
}

/// Each place on the body says yes or no for the thing being carried over it, and the answer is
/// not the slot's own list of places alone.
///
/// Six stations, and the last two are the ones that matter: a torch may be held, so the weapon
/// hand says yes in peace and no with the weapon out -- the slot's list passes both times and
/// only the wield rule tells them apart.
pub fn a_body_slot_shows_whether_it_could_take_what_is_carried() {
    let mut c = a_client_with_four_things();
    let shield_slot = doll_tile(&mut c, DOLL_SHIELD_SLOT);
    let weapon_slot = doll_tile(&mut c, DOLL_WEAPON_SLOT);
    let nothing_yet = doll_hint(&mut c, DOLL_SHIELD_SLOT).is_none();

    // A rock can go nowhere, so the shield slot refuses it.
    let (rock_on_shield, _) = hints_while_carrying(&mut c, PLAIN_ROCK, shield_slot);
    // A shield is not a weapon, so the weapon hand refuses it...
    let (_, shield_on_weapon) = hints_while_carrying(&mut c, SHIELD, weapon_slot);
    // ...and its own slot takes it, with the weapon hand saying nothing about it.
    let (shield_on_shield, weapon_untouched) = hints_while_carrying(&mut c, SHIELD, shield_slot);
    // A one-handed sword is taken in the shield slot too: that is the alias the client carries.
    let (sword_on_shield, _) = hints_while_carrying(&mut c, SWORD, shield_slot);
    // A torch may be held, and in peace the weapon hand takes it.
    let (_, torch_at_peace) = hints_while_carrying(&mut c, TORCH, weapon_slot);
    c.app_mut().objects_mut().world.combat.combat_mode =
        dereth_client_model::combat::CombatMode::Melee;
    c.tick(1);
    // With the weapon out, the same hand refuses the same torch.
    let (_, torch_in_combat) = hints_while_carrying(&mut c, TORCH, weapon_slot);

    let accept = Some(drag_accept_state::ACCEPT);
    let refuse = Some(drag_accept_state::REFUSE);
    c.assert_behaviour(
        "inventory.drag-hint.a-body-slot-shows-whether-it-could-take-what-is-carried",
        move |_| {
            nothing_yet
                && rock_on_shield == refuse
                && shield_on_weapon == refuse
                && shield_on_shield == accept
                && weapon_untouched != accept
                && sword_on_shield == accept
                && torch_at_peace == accept
                && torch_in_combat == refuse
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag-hint.a-shortcut-tile-offers-itself-for-anything-carried
// ---------------------------------------------------------------------------------------------

/// A shortcut tile says yes to anything carried over it, and says nothing again when the pointer
/// moves off -- it is a place to keep a reference to a thing, so nothing about the thing itself
/// can refuse it.
pub fn a_shortcut_tile_offers_itself_for_anything_carried() {
    let mut c = a_client_with_four_things();
    let nothing_yet = shortcut_hint(&mut c, 0).is_none();
    let tile = shortcut_tile(&mut c, 0);

    let rock = pack_slot(&mut c, PLAIN_ROCK);
    let from = point_of(&mut c, rock);
    c.when(Grab(from));
    carry_over(&mut c, tile);
    let offered = shortcut_hint(&mut c, 0);

    let torch = pack_slot(&mut c, TORCH);
    let at = carry_over(&mut c, torch);
    let taken_back = shortcut_hint(&mut c, 0);
    c.when(LetGo(at));
    clear_requests(c.ui_outbox());

    c.assert_behaviour(
        "inventory.drag-hint.a-shortcut-tile-offers-itself-for-anything-carried",
        move |_| {
            nothing_yet
                && offered == Some(drag_accept_state::ACCEPT)
                && taken_back == Some(drag_accept_state::NONE)
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.drag-hint.letting-go-on-a-tile-takes-its-own-hint-down
// ---------------------------------------------------------------------------------------------

/// Letting go **on** the tile that is lit takes its hint down, on the element as well as in the
/// panel's own record, and ends the drag.
///
/// This is the half a scenario that only ever moves the pointer away cannot see: the hint could
/// be cleared by the leave alone and a drop would leave it standing for the rest of the session.
pub fn letting_go_on_a_tile_takes_its_own_hint_down() {
    let mut c = a_client_with_four_things();
    let tile = shortcut_tile(&mut c, 0);
    let nothing_yet = shortcut_hint(&mut c, 0).is_none();

    let rock = pack_slot(&mut c, PLAIN_ROCK);
    let from = point_of(&mut c, rock);
    c.when(Grab(from));
    let at = carry_over(&mut c, tile);
    let lit = shortcut_hint(&mut c, 0) == Some(drag_accept_state::ACCEPT)
        && shortcut_overlay(&mut c, 0) == drag_accept_state::ACCEPT;

    c.when(LetGo(at));
    clear_requests(c.ui_outbox());
    let down = shortcut_hint(&mut c, 0) == Some(drag_accept_state::NONE)
        && shortcut_overlay(&mut c, 0) == drag_accept_state::NONE;
    let over_now = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        ui.drag_state().element.is_none()
    };

    c.assert_behaviour(
        "inventory.drag-hint.letting-go-on-a-tile-takes-its-own-hint-down",
        move |_| nothing_yet && lit && down && over_now,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.wear.dropping-a-worn-thing-back-on-its-own-slot-says-it-is-already-worn
// ---------------------------------------------------------------------------------------------

/// Put `id` on the body, through the placement the client's own rebuild derives its masks from.
fn wear_it(
    w: &mut dereth_client_model::World,
    id: ObjectId,
    location: u32,
    priority: u32,
    name: &str,
) {
    let mut wn = dereth_client_model::Weenie::new(id);
    wn.valid = true;
    wn.pwd.name = name.into();
    wn.pwd.valid_locations = Some(location);
    wn.pwd.priority = Some(priority);
    wn.pwd.container_id = Some(HINT_PLAYER);
    wn.pwd.wielder_id = Some(HINT_PLAYER);
    wn.pwd.location = Some(location);
    w.tables.weenies.insert(id, wn);
    w.tables
        .inventories
        .get_mut(HINT_PLAYER)
        .expect("seeded")
        .set_placement(id, location, priority);
    w.remake_character_inventory();
}

/// A client wearing one thing on its chest, named however the caller asks.
fn a_client_wearing_something(material: Option<u32>) -> HeadlessClient {
    let mut c = a_client_with_four_things();
    {
        let w = &mut c.app_mut().objects_mut().world;
        wear_it(
            w,
            SHIRT,
            dereth_client_model::inventory::slots::loc::CHEST_WEAR,
            0x20,
            "obj14",
        );
        if let Some(m) = material {
            let wn = w.tables.weenies.get_mut(SHIRT).expect("worn");
            wn.pwd.name = "Breastplate".into();
            wn.pwd.plural_name = None;
            wn.pwd.material_type = Some(m);
            wn.pwd.stack_size = Some(1);
        }
    }
    c.tick(2);
    assert_eq!(
        doll_item(&mut c, DOLL_SHIRT_SLOT),
        Some(SHIRT),
        "the premise: it is on the body before it is dragged off it"
    );
    c
}

/// Drag the worn thing off its own slot and drop it straight back on: the lines that appear, and
/// whether the hint said yes on the way.
fn drop_it_back_on(c: &mut HeadlessClient) -> (Vec<String>, bool, bool) {
    let slot = doll_tile(c, DOLL_SHIRT_SLOT);
    let before = strip_lines(c);
    let from = point_of(c, slot);
    c.when(Grab(from));
    let at = carry_over(c, slot);
    let green_on_the_way = doll_hint(c, DOLL_SHIRT_SLOT) == Some(drag_accept_state::ACCEPT);
    c.when(LetGo(at));
    clear_requests(c.ui_outbox());
    let after = strip_lines(c);
    let new_lines: Vec<String> = after.into_iter().skip(before.len()).collect();
    let not_ghosted = !c
        .app_mut()
        .objects()
        .world
        .weenie(SHIRT)
        .expect("worn")
        .waiting;
    (new_lines, green_on_the_way, not_ghosted)
}

/// A worn thing dropped back on the place it is already worn is refused in the client's own
/// words, and the words name the thing the way the player sees it named.
///
/// The hint on the way over says yes, deliberately: there is no exception for the slot a thing
/// came from, and the refusal is the drop's, not the hover's.
pub fn dropping_a_worn_thing_back_on_its_own_slot_says_so() {
    let mut plain_client = a_client_wearing_something(None);
    let (plain, green, not_ghosted) = drop_it_back_on(&mut plain_client);
    plain_client.shutdown();
    let says_it_plainly = plain.iter().any(|l| l == "The obj14 is already being worn");

    let mut c = a_client_wearing_something(Some(0x3A));
    let (with_material, _, _) = drop_it_back_on(&mut c);
    let says_the_material_too = with_material
        .iter()
        .any(|l| l == "The Bronze Breastplate is already being worn");

    c.assert_behaviour(
        "inventory.wear.dropping-a-worn-thing-back-on-its-own-slot-says-it-is-already-worn",
        move |_| green && says_it_plainly && says_the_material_too && not_ghosted,
    );
    c.shutdown();
}

