// =============================================================================================
// The three things that tell a player whether a drop will be taken, and why not.
//
// Three failures, all about the same absence: the client took the drop or refused it and said
// nothing either way. What the shop says while something is carried over it, the mark a thing wears
// once it has been offered, and the sentence the player reads when the shard says no.
//
// The two cursor answers are the two arms of one decision and are one row; the two world-drop
// refusals are one claim measured twice -- the sentence, and the name inside it -- and are one
// row that asserts both sentences.
// =============================================================================================

/// The recorded shop, her sell list and the tab that raises it.
const SELL_TAB: ElementId = ElementId(0x1000_00BB);
/// The two answers the shop's own hover gives.
const HINT_ACCEPT: StateId = StateId(0x1000_0040);
const HINT_REFUSE: StateId = StateId(0x1000_0041);

/// The book the recording puts into a container on the landscape, and the container.
const BOOK: ObjectId = ObjectId(0x8000_0A22);
const BOOK_CONTAINER: ObjectId = ObjectId(0x8000_0997);
const BOOK_PUT_AT: usize = 2674;
const BOOK_REFUSAL_AT: usize = 2675;

/// The thing the recording drops into the world, and the refusal that comes back.
const FOCI: ObjectId = ObjectId(0x8000_099E);
const FOCI_DROP_AT: usize = 4025;
const FOCI_REFUSAL_AT: usize = 4026;

/// The one recorded appraisal in the whole corpus that carries the attuned property.
const ATTUNED_SUBJECT: ObjectId = ObjectId(0x8000_0A99);
const ATTUNED_APPRAISAL_AT: usize = 6683;

/// A client with the recording replayed up to and including blob `idx`.
fn a_client_played_to(idx: usize) -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    // The identity is chosen before the description arrives, and a corpus replay carries no
    // login step to carry it across.
    c.world_mut().player = Some(RECORDED_PLAYER);
    c.when(Inbound::from_corpus("long-solo-play", 0..idx + 1))
        .tick(4);
    c
}

/// One more recorded blob, by index.
fn one_more_blob(c: &mut HeadlessClient, idx: usize) {
    c.when(Inbound::from_corpus("long-solo-play", idx..idx + 1))
        .tick(3);
}

/// Everything the feedback strip has been given, drawn or not.
fn feedback(c: &HeadlessClient) -> Vec<String> {
    let m = &c.view().expect_app().hud().panels.spew.model;
    m.pending.iter().chain(m.items.iter()).cloned().collect()
}

/// The shop open on its **Selling** tab, with the player's own pack page up behind it.
fn a_client_at_the_shop_selling() -> HeadlessClient {
    let mut c = a_client_at_the_shop();
    let tab = element_of(&c, SELL_TAB);
    {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.broadcast_element_message(
            tab,
            dereth_ui::msg::element::id::BUTTON_CLICKED,
            dereth_ui::focus::action::PRIMARY_CLICK,
            0,
        );
    }
    c.tick(3);
    assert!(
        c.view().expect_app().hud().panels.vendor.sell.is_some(),
        "the premise: the shop's sell list is bound"
    );
    c
}

/// A thing in the player's pack the shop would buy, and one she would not.
fn something_she_takes_and_something_she_will_not(
    c: &mut HeadlessClient,
) -> (
    Option<(ElemHandle, ObjectId)>,
    Option<(ElemHandle, ObjectId)>,
) {
    let app = c.view().expect_app();
    let world = &app.objects().world;
    let shell = app.ui().expect("the UI shell");
    let any: &dyn std::any::Any = shell.flow.current().expect("a screen");
    let screen = any
        .downcast_ref::<GamePlayScreen>()
        .expect("the gameplay screen");
    let (mut good, mut bad) = (None, None);
    for w in screen.inventory.item_list.iter() {
        for s in &w.slots {
            let Some(id) = s.item else { continue };
            let Some(o) = world.weenie(id) else { continue };
            if !world.is_owned_by_player(id) {
                continue;
            }
            let empty = world
                .inventory(id)
                .is_none_or(|i| i.items.is_empty() && i.containers.is_empty());
            if !empty {
                continue;
            }
            if world.shop.profile.inq_acceptability(&o.pwd) == 0 {
                good.get_or_insert((s.handle, id));
            } else {
                bad.get_or_insert((s.handle, id));
            }
        }
    }
    (good, bad)
}

/// The shop's first sell tile, and what its own hint element is showing.
fn sell_tile(c: &HeadlessClient) -> (ElemHandle, Option<StateId>) {
    let list = c
        .view()
        .expect_app()
        .hud()
        .panels
        .vendor
        .sell
        .as_ref()
        .expect("the shop's sell list is bound");
    let s = list.slots.first().expect("the list keeps its empty tiles");
    (s.handle, s.drag_accept_state)
}

/// Pick a pack tile up and carry the icon over `over`.
///
/// **Not driven through the pointer, and the reason is the layout and not the gesture.** At this
/// screen size the shop sits over the player's pack, so with the shop up no tile of the pack grid
/// is the element under its own centre -- a pointer aimed at one reaches the shop's own buttons.
/// That is a fact about where two windows are, which a player changes by moving one, and driving
/// the pointer here would be asserting the layout. Every handler on the path below is still the
/// production one: the drag is begun by the list's own producer at the point the tile is at, and
/// the hover is the message the element manager raises when the pointer enters something.
fn carry_icon_over(c: &mut HeadlessClient, from: ElemHandle, over: ElemHandle) {
    let (x, y) = {
        let (ui, _root) = gameplay_root(c.app_mut());
        centre(ui, from)
    };
    {
        let app = c.app_mut();
        let shell = app.ui_mut().expect("the UI shell");
        let any: &mut dyn std::any::Any = &mut **shell.flow.current_mut().expect("a screen");
        let screen = any
            .downcast_mut::<GamePlayScreen>()
            .expect("the gameplay screen");
        screen
            .begin_item_drag(&mut shell.ui, from, x, y)
            .expect("the tile starts a drag");
    }
    c.tick(1);
    assert!(
        {
            let (ui, _root) = gameplay_root(c.app_mut());
            ui.drag_state().element.is_some()
        },
        "the premise: the tile made a proxy, or there is nothing to hint about"
    );
    {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.broadcast_element_message(over, dereth_ui::msg::element::id::DRAG_CURSOR_OVER, 1, 0);
    }
    c.tick(3);
}

// ---------------------------------------------------------------------------------------------
// vendor.sell.the-window-says-whether-it-would-buy-what-is-carried-over-it
// ---------------------------------------------------------------------------------------------

/// Carrying something over a shop's sell window shows whether she would buy it: one answer for
/// something she takes and a different one for something she will not.
///
/// Both arms are one scenario because they are the two answers to one question, and a client that
/// painted the same thing for both would be no better than the one that painted nothing. The
/// control is asserted first: the tile is not already showing the accepting answer before anything
/// is carried over it.
pub fn the_shop_says_whether_it_would_buy_what_is_carried_over_it() {
    // **One client at a time.** Two live ones in this process share the shell's request globals,
    // which is why this binary runs serially at all, so the first arm is shut down before the
    // second is built.
    let takes_it = {
        let mut c = a_client_at_the_shop_selling();
        let (good, _) = something_she_takes_and_something_she_will_not(&mut c);
        let (from, _) = good.expect("the recorded pack carries something this shop accepts");
        let (tile, before) = sell_tile(&c);
        assert_ne!(
            before,
            Some(HINT_ACCEPT),
            "the premise: the answer is not already showing"
        );
        carry_icon_over(&mut c, from, tile);
        let answer = sell_tile(&c).1 == Some(HINT_ACCEPT);
        c.shutdown();
        answer
    };

    let mut c = a_client_at_the_shop_selling();
    let (_, bad) = something_she_takes_and_something_she_will_not(&mut c);
    let (from_bad, _) = bad.expect("the recorded pack carries something this shop refuses");
    let (tile, _) = sell_tile(&c);
    carry_icon_over(&mut c, from_bad, tile);
    let will_not = sell_tile(&c).1 == Some(HINT_REFUSE);

    c.assert_behaviour(
        "vendor.sell.the-window-says-whether-it-would-buy-what-is-carried-over-it",
        move |_| takes_it && will_not,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// vendor.tabs.something-carried-over-the-window-turns-it-to-the-selling-tab
// ---------------------------------------------------------------------------------------------

/// Carrying something over the shop window turns it to the Selling tab by itself -- over any
/// part of the window, here the stock list on the Items page -- and the pointer over the same
/// spot with nothing carried leaves the page alone.
pub fn something_carried_over_the_window_turns_it_to_the_selling_tab() {
    use dereth_ui_screens::panels::vendor::{PAGE_ITEMS, PAGE_SELL, STOCK_LIST};
    let page = |c: &HeadlessClient| {
        c.view()
            .expect_app()
            .hud()
            .panels
            .vendor
            .open_page(&c.view().expect_app().ui().expect("the UI shell").ui)
    };
    let mut c = a_client_at_the_shop();
    let starts_on_items = page(&c) == Some(PAGE_ITEMS);
    let (from, _item) = sellable(&c);
    let stock = element_of(&c, STOCK_LIST);
    let (sx, sy) = {
        let (ui, _root) = gameplay_root(c.app_mut());
        centre(ui, stock)
    };

    // The pointer over the stock list with nothing in hand.
    {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.mouse_move(LocalTime(1.0), sx, sy);
    }
    c.tick(3);
    let empty_handed_stays = page(&c) == Some(PAGE_ITEMS);

    // The same spot with the stack in hand.
    let (fx, fy) = {
        let (ui, _root) = gameplay_root(c.app_mut());
        centre(ui, from)
    };
    {
        let app = c.app_mut();
        let shell = app.ui_mut().expect("the UI shell");
        let any: &mut dyn std::any::Any = &mut **shell.flow.current_mut().expect("a screen");
        let screen = any
            .downcast_mut::<GamePlayScreen>()
            .expect("the gameplay screen");
        screen
            .begin_item_drag(&mut shell.ui, from, fx, fy)
            .expect("the tile starts a drag");
    }
    c.tick(1);
    let carrying = {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.is_dragging()
    };
    {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.mouse_move(LocalTime(2.0), sx, sy);
    }
    c.tick(3);
    let turned_to_selling = page(&c) == Some(PAGE_SELL);

    c.assert_behaviour(
        "vendor.tabs.something-carried-over-the-window-turns-it-to-the-selling-tab",
        move |_| starts_on_items && empty_handed_stays && carrying && turned_to_selling,
    );
    c.shutdown();
}

#[test]
fn scenario_something_carried_over_the_window_turns_it_to_the_selling_tab() {
    scenario("something_carried_over_the_window_turns_it_to_the_selling_tab");
}

// ---------------------------------------------------------------------------------------------
// vendor.sell.something-offered-wears-the-mark-in-the-pack-as-well-as-in-the-window
// ---------------------------------------------------------------------------------------------

/// A thing put into the shop's sell list wears the offered mark **in the player's own pack as
/// well as in the window**.
///
/// One thing is being drawn in two places and the mark belongs to the thing, not to either list,
/// which is the whole of the claim. The mark is read off the live element and not off the list's
/// record of it, because a list that remembered the flag and never raised the element is exactly
/// the failure this guards against.
pub fn something_offered_to_the_shop_wears_the_mark_in_both_windows() {
    let mut c = a_client_at_the_shop_selling();
    let (good, _) = something_she_takes_and_something_she_will_not(&mut c);
    let (from, item) = good.expect("the recorded pack carries something this shop accepts");
    let list = element_of(&c, SELL_LIST);

    {
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.broadcast_element_message(
            list,
            dereth_ui::msg::element::id::DROP_FAILED,
            0,
            from.raw(),
        );
    }
    c.tick(4);

    let offered = c
        .view()
        .world()
        .weenie(item)
        .expect("the offered thing")
        .sell_state
        == 1;

    let marks = |c: &HeadlessClient, slot: &dereth_ui_screens::items::widget::ItemSlot| {
        let h = slot
            .sell_state_elem
            .expect("every tile binds the offered mark");
        let ui = &c.view().expect_app().ui().expect("the UI shell").ui;
        (
            slot.sell_state,
            ui.node(h).expect("live").region.flags.visible,
        )
    };
    let in_the_pack = {
        let app = c.view().expect_app();
        let shell = app.ui().expect("the UI shell");
        let any: &dyn std::any::Any = shell.flow.current().expect("a screen");
        any.downcast_ref::<GamePlayScreen>()
            .expect("the gameplay screen")
            .inventory
            .item_list
            .iter()
            .flat_map(|w| w.slots.iter())
            .find(|s| s.item == Some(item) && s.handle == from)
            .map(|s| marks(&c, s))
            .expect("the pack tile the drag started from still holds the thing")
    };
    let in_the_window = {
        let app = c.view().expect_app();
        app.hud()
            .panels
            .vendor
            .sell
            .as_ref()
            .expect("the sell list")
            .slots
            .iter()
            .find(|s| s.item == Some(item))
            .map(|s| marks(&c, s))
            .expect("the sell list now holds the thing")
    };

    c.assert_behaviour(
        "vendor.sell.something-offered-wears-the-mark-in-the-pack-as-well-as-in-the-window",
        move |_| offered && in_the_pack == (true, true) && in_the_window == (true, true),
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.refusal.a-world-drop-the-shard-refuses-names-the-thing-as-the-player-sees-it
// ---------------------------------------------------------------------------------------------

/// When the shard refuses a thing dropped into the world, the player is told so in a sentence
/// naming the thing the way they see it named -- material and all.
///
/// Both halves are the recording's own: the thing, the request the recorded client made, and the
/// refusal that came back. The second measurement changes only the thing's own description, into
/// one that carries a material, so that what is isolated is the naming and not the refusal.
pub fn a_refused_world_drop_names_the_thing_as_the_player_sees_it() {
    let mut c = a_client_played_to(FOCI_DROP_AT - 1);
    let name = c
        .view()
        .world()
        .weenie(FOCI)
        .expect("the recording creates it")
        .pwd
        .name
        .clone();
    assert_eq!(
        name, "Foci of Enchantment",
        "the premise: the recording's own thing"
    );

    // The request the recorded client made, at the producer that records what kind it is --
    // which is what picks the sentence. Letting go over the world only *arms* a pick, and the
    // hop after it needs a rendered scene and a body on the ground, which is another row's.
    let mut req = dereth_client_model::RecordingRequests::default();
    let mut out = dereth_client_model::RecordingSink::default();
    c.app_mut()
        .objects_mut()
        .world
        .attempt_put_in_3d(&mut req, &mut out, FOCI, ServerTime(1.0), false)
        .expect("the premise: nothing else is in flight at this point of the recording");
    assert!(
        req.0
            .iter()
            .any(|r| matches!(r, Request::DropItem(m) if m.item == FOCI)),
        "the premise: this is the drop the recording's next blob answers"
    );

    one_more_blob(&mut c, FOCI_REFUSAL_AT);
    let said_so = feedback(&c)
        .iter()
        .any(|l| l == "The Foci of Enchantment can't be dropped");
    // One client at a time: see the shop scenario above.
    c.shutdown();

    // The same real request and the same recorded refusal, with the thing described with a
    // material in its name.
    let mut c = a_client_played_to(FOCI_DROP_AT - 1);
    let mapper_knows_it = dereth_client::hud::material_name_of(
        c.view().expect_app().hud().material_names.as_ref(),
        0x3A,
    )
    .as_deref()
        == Some("Bronze");
    assert!(
        mapper_knows_it,
        "the premise: the shipped material table is the prefix's oracle"
    );
    {
        let item = c
            .app_mut()
            .objects_mut()
            .world
            .weenie_mut(FOCI)
            .expect("the recorded thing");
        item.pwd.name = "Salvage (100)".into();
        item.pwd.plural_name = None;
        item.pwd.material_type = Some(0x3A);
        item.pwd.stack_size = Some(1);
    }
    let mut req = dereth_client_model::RecordingRequests::default();
    let mut out = dereth_client_model::RecordingSink::default();
    c.app_mut()
        .objects_mut()
        .world
        .attempt_put_in_3d(&mut req, &mut out, FOCI, ServerTime(1.0), false)
        .expect("the premise: the same producer takes the same thing");
    assert!(req
        .0
        .iter()
        .any(|r| matches!(r, Request::DropItem(m) if m.item == FOCI)));
    one_more_blob(&mut c, FOCI_REFUSAL_AT);
    let named_its_material = feedback(&c)
        .iter()
        .any(|l| l == "The Bronze Salvage (100) can't be dropped");

    c.assert_behaviour(
        "inventory.refusal.a-world-drop-the-shard-refuses-names-the-thing-as-the-player-sees-it",
        move |_| said_so && named_its_material,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.refusal.a-container-drop-the-shard-refuses-says-so-in-its-own-words
// ---------------------------------------------------------------------------------------------

/// A thing the shard refuses to let into a container is refused in the container's own sentence,
/// which is not the one a refused world drop gets.
///
/// Two refusals of the same kind from the same answer, and which one the player reads is decided
/// by what the client recorded itself as asking for. The recording is the oracle for both ends:
/// the request its own client sent and the refusal that came back.
pub fn a_refused_container_drop_says_so_in_its_own_words() {
    let mut c = a_client_played_to(BOOK_PUT_AT - 1);
    let name = c
        .view()
        .world()
        .weenie(BOOK)
        .expect("the recording creates it")
        .pwd
        .name
        .clone();
    assert_eq!(
        name, "Restoring the Training Academies",
        "the premise: the recording's own thing"
    );

    let mark = c.outbound().len();
    c.when(Player::Ui(vec![UiRequest::DragDrop {
        item: BOOK,
        target: DropTarget::Container(BOOK_CONTAINER),
    }]))
    .tick(3);
    assert!(
        sent_since(&c, mark)
            .iter()
            .any(|r| matches!(r, Request::PutItemInContainer(m) if m.item == BOOK)),
        "the premise: this is the move the recording's next blob answers"
    );

    one_more_blob(&mut c, BOOK_REFUSAL_AT);
    let said_so = feedback(&c)
        .iter()
        .any(|l| l == "The Restoring the Training Academies can't be put in the container");

    c.assert_behaviour(
        "inventory.refusal.a-container-drop-the-shard-refuses-says-so-in-its-own-words",
        move |_| said_so,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.attunement.an-attuned-thing-says-so-in-its-description
// ---------------------------------------------------------------------------------------------

/// A thing that cannot be dropped says so in its own description, before the player tries.
///
/// That is the other half of a refused drop, and the half that saves the player the attempt. The
/// recording carries exactly one appraisal with the attuned property in it and it carries the
/// bonded one too; both are drawn, in that order, under one heading.
pub fn an_attuned_thing_says_so_in_its_description() {
    let mut c = a_client_played_to(ATTUNED_APPRAISAL_AT - 1);
    // The recorded answer itself, read out of the corpus, so that a failure in the pane cannot
    // be blamed on the decode.
    let profile = {
        let corpus = Corpus::load("long-solo-play")
            .expect("the recording parses")
            .expect("the corpus carries this recording");
        let row = corpus
            .blobs
            .iter()
            .find(|b| b.idx == ATTUNED_APPRAISAL_AT)
            .expect("the recorded index exists");
        let mut rd = dereth_protocol::archive::Reader::new(&row.payload[16..]);
        let m = <dereth_protocol::objects::ItemSetAppraiseInfo as dereth_protocol::Message>::read(
            &mut rd,
        )
        .expect("the recorded appraisal decodes");
        assert_eq!(
            m.object, ATTUNED_SUBJECT,
            "the premise: it is about this thing"
        );
        let ints = m
            .profile
            .tables
            .ints
            .as_ref()
            .expect("the recorded answer has an int table");
        assert!(
            ints.entries.contains(&(114, 1)),
            "the premise: it says the thing is attuned"
        );
        assert!(
            ints.entries.contains(&(33, 1)),
            "the premise: and that it is bonded"
        );
        m.profile
    };

    {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        screen.examination.examine_object(ATTUNED_SUBJECT);
    }
    {
        let mut sink = dereth_client_model::RecordingSink::default();
        c.app_mut()
            .objects_mut()
            .world
            .set_appraise_info(ATTUNED_SUBJECT, profile, &mut sink);
    }
    c.tick(1);

    let text = {
        let (_ui, screen) = gameplay_screen(c.app_mut());
        screen
            .examination
            .item_text
            .clone()
            .expect("the item pane is written")
    };
    let says_both_in_order = text.contains("Properties: Attuned, Bonded");

    c.assert_behaviour(
        "inventory.attunement.an-attuned-thing-says-so-in-its-description",
        move |_| says_both_in_order,
    );
    c.shutdown();
}

