// =============================================================================================
// The figure's picture on the live tree.
//
// The figure's other claims need no retail data file and are in the cpu tier; these two are about
// the shipped tree: that the picture is a place to let something go beside the twenty-four places,
// and that asking for the grid of places takes the picture out of the hit test rather than out of
// the map.
// =============================================================================================

/// The figure's viewport, its own answer overlay and the checkbox: three more things the window
/// binds, and none of them a place to let something go.
const FIGURE_VIEWPORT: ElementId = ElementId(0x1000_01D5);
const FIGURE_ANSWER_OVERLAY: ElementId = ElementId(0x1000_046D);
const PLACES_CHECKBOX: ElementId = ElementId(0x1000_05BE);

// ---------------------------------------------------------------------------------------------
// inventory.body.the-picture-of-the-character-is-a-twenty-fifth-place-to-let-something-go
// ---------------------------------------------------------------------------------------------

/// The figure takes a drop on the picture of the character as well as on each of its
/// twenty-four places -- twenty-five in all -- and nothing else the window binds takes one.
///
/// The picture is the one that was missing: a drag released on the character's own body named no
/// target at all, so the request went nowhere and the icon was not even put back.
pub fn the_picture_of_the_character_is_a_twenty_fifth_place_to_let_something_go() {
    let mut c = a_client_with_three_things_and_a_pack();

    let picture = shipped(&mut c, PAPER_DOLL_DRAG_MASK);
    let others: Vec<(ElementId, ElemHandle)> =
        [FIGURE_VIEWPORT, FIGURE_ANSWER_OVERLAY, PLACES_CHECKBOX]
            .into_iter()
            .map(|id| (id, shipped(&mut c, id)))
            .collect();

    let (_ui, screen) = gameplay_screen(c.app_mut());
    let inv = &screen.inventory;

    let mut targets: std::collections::BTreeSet<u32> = std::collections::BTreeSet::new();
    let mut every_place_takes_one = true;
    for (_, w) in &inv.doll {
        every_place_takes_one &=
            inv.drop_target(w.handle) == Some(equipment_destination(w.element.0));
        targets.insert(w.element.0);
    }
    let twenty_four_places = targets.len() == 24;

    let the_picture_takes_one = inv.drop_target(picture) == Some(DropTarget::EquipCanvas);
    targets.insert(PAPER_DOLL_DRAG_MASK.0);
    let twenty_five_in_all = targets.len() == 25;
    let nothing_else_does = others.iter().all(|(_, h)| inv.drop_target(*h).is_none());

    c.assert_behaviour(
        "inventory.body.the-picture-of-the-character-is-a-twenty-fifth-place-to-let-something-go",
        move |_| {
            every_place_takes_one
                && twenty_four_places
                && the_picture_takes_one
                && twenty_five_in_all
                && nothing_else_does
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.body.asking-for-the-grid-of-places-takes-the-picture-out-of-the-hit-test
// ---------------------------------------------------------------------------------------------

/// Asking for the grid of places switches the picture **off**, so a pointer over where it was
/// no longer finds it -- while the map of what takes a drop is unchanged. It is the hit test
/// that moves, not the producer.
///
/// The visibility itself is asserted and not only the hit test, and the reason is a measurement:
/// the grid of places covers the same rectangle, and the walk that finds what is under the
/// pointer answers the last child first, so one of the places answers whether the picture was
/// switched off or not. A scenario that only asked what is under the pointer would pass with the
/// picture still on.
pub fn asking_for_the_grid_of_places_takes_the_picture_out_of_the_hit_test() {
    let mut c = a_client_with_three_things_and_a_pack();
    let picture = shipped(&mut c, PAPER_DOLL_DRAG_MASK);
    let (x, y) = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        centre(ui, picture)
    };

    // The state the window is shipped in, which is what a player sees first.
    let (showing_the_picture, the_pointer_finds_it) = {
        let (ui, screen) = gameplay_screen(c.app_mut());
        (
            !screen.inventory.slots_view,
            ui.hit_test_screen(x, y) == Some(picture),
        )
    };

    {
        let (ui, screen) = gameplay_screen(c.app_mut());
        screen.inventory.set_slot_view(ui, true);
    }
    c.tick(1);

    let (switched_off, the_pointer_no_longer_finds_it, the_map_is_unchanged) = {
        let (ui, screen) = gameplay_screen(c.app_mut());
        (
            !ui.node(picture).expect("alive").region.flags.visible,
            ui.hit_test_screen(x, y) != Some(picture),
            screen.inventory.drop_target(picture) == Some(DropTarget::EquipCanvas),
        )
    };

    c.assert_behaviour(
        "inventory.body.asking-for-the-grid-of-places-takes-the-picture-out-of-the-hit-test",
        move |_| {
            showing_the_picture
                && the_pointer_finds_it
                && switched_off
                && the_pointer_no_longer_finds_it
                && the_map_is_unchanged
        },
    );
    c.shutdown();
}

#[test]
fn scenario_the_picture_of_the_character_is_a_twenty_fifth_place_to_let_something_go() {
    scenario("the_picture_of_the_character_is_a_twenty_fifth_place_to_let_something_go");
}

#[test]
fn scenario_asking_for_the_grid_of_places_takes_the_picture_out_of_the_hit_test() {
    scenario("asking_for_the_grid_of_places_takes_the_picture_out_of_the_hit_test");
}

// =============================================================================================
// Clicking the picture of the character.
//
// A click on the paper doll selects the item worn there, without first switching the window to
// its grid of item slots.
//
// The grid of places is a list, so a click on one of its cells selects the ordinary way. The
// **picture** is not a list at all: which part of the body the pointer is over is read out of a
// painted picture shipped with the client, and a scenario whose coordinates were written down
// rather than found in that picture would be measuring nothing. So the first scenario below
// measures the shipped picture, and the two after it take their points from it.
// =============================================================================================

use dereth_client_model::objects::InventoryPlacement;
use dereth_ui_screens::panels::inventory::{ClickMap, HIT_TEST_COLOURS};

/// The player who is clicked on.
const CLICKED_PLAYER: ObjectId = ObjectId(0x5000_0001);
/// A breastplate: chest **armour**.
const CHEST_ARMOUR: ObjectId = ObjectId(0x8000_1001);
/// A shirt: chest **clothing**, which the painted picture cannot tell apart from the armour.
const CHEST_SHIRT: ObjectId = ObjectId(0x8000_1002);

/// A player wearing a breastplate over a shirt, with the pack page up.
///
/// The two are worn in the same region of the picture on purpose: that is the case where what is
/// selected is decided by which of them is on top, and a client that answered with whichever it
/// met first would pass every other measurement here.
fn a_client_with_a_dressed_chest() -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    {
        let world = &mut c.app_mut().objects_mut().world;
        world.player = Some(CLICKED_PLAYER);
        let mut inv = dereth_client_model::objects::ObjectInventory::new(CLICKED_PLAYER);
        inv.placements = vec![
            InventoryPlacement {
                iid: CHEST_ARMOUR,
                loc: 0x0000_0200,
                priority: 0,
            },
            InventoryPlacement {
                iid: CHEST_SHIRT,
                loc: 0x0000_0002,
                priority: 0,
            },
        ];
        world.tables.inventories.insert(CLICKED_PLAYER, inv);
    }
    open_pack(&mut c);
    c.tick(4);
    c
}

/// The picture the client reads the body region out of.
fn the_painted_picture(c: &mut HeadlessClient) -> ClickMap {
    let (_ui, screen) = gameplay_screen(c.app_mut());
    screen
        .inventory
        .click_map
        .clone()
        .expect("the shipped picture is loaded when the window comes up")
}

/// The first point of the picture painted for `region`, in the picture's own coordinates.
fn a_point_painted_for(map: &ClickMap, region: u32) -> (i32, i32) {
    for y in 0..map.height {
        for x in 0..map.width {
            if map.mask_at(x, y) == region {
                return (x, y);
            }
        }
    }
    panic!("the shipped picture paints no point for the region {region:#06X}")
}

/// A point of the picture, as a point on screen.
fn on_screen(c: &mut HeadlessClient, point: (i32, i32)) -> Target {
    let picture = shipped(c, PAPER_DOLL_DRAG_MASK);
    let (x0, y0) = {
        let (ui, _screen) = gameplay_screen(c.app_mut());
        ui.screen_origin(picture)
    };
    Target::Point(ScreenPoint::new(x0 + point.0, y0 + point.1))
}

// ---------------------------------------------------------------------------------------------
// inventory.body.the-shipped-picture-of-the-character-is-painted-for-every-region
// ---------------------------------------------------------------------------------------------

/// The picture the client reads a body region out of is painted for **all nine** regions, and a
/// point outside it belongs to no region at all.
///
/// The count is what matters. A picture with, say, no points painted for the lower leg would let
/// every other measurement pass while one part of the body stayed dead to the pointer -- which
/// is the shape of the whole complaint.
pub fn the_shipped_picture_of_the_character_is_painted_for_every_region() {
    let mut c = a_client_with_a_dressed_chest();
    let map = the_painted_picture(&mut c);

    let mut painted = 0usize;
    let mut unpainted = 0usize;
    for (_colour, region) in HIT_TEST_COLOURS {
        let mut n = 0u32;
        for y in 0..map.height {
            for x in 0..map.width {
                if map.mask_at(x, y) == region {
                    n += 1;
                }
            }
        }
        if n == 0 {
            unpainted += 1;
        } else {
            painted += 1;
        }
    }
    let nine = HIT_TEST_COLOURS.len() == 9;
    let all_painted = unpainted == 0 && painted == 9;
    let off_the_picture_is_no_region = map.mask_at(-1, 0) == 0 && map.mask_at(0, map.height) == 0;

    c.assert_behaviour(
        "inventory.body.the-shipped-picture-of-the-character-is-painted-for-every-region",
        move |_| nine && all_painted && off_the_picture_is_no_region,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.body.a-click-on-the-picture-selects-what-is-worn-in-that-region
// ---------------------------------------------------------------------------------------------

/// A click on a part of the picture of the character selects what the player is wearing there --
/// and when two things are worn in the same part, the one that is **on top**.
///
/// The picture cannot tell the shirt from the breastplate: they share the same painted region,
/// so a client that answered with whichever it met first would answer the shirt half the time.
/// The premise is asserted first: the click really does land on the picture, and nothing is
/// selected before it.
pub fn a_click_on_the_picture_selects_what_is_worn_in_that_region() {
    let mut c = a_client_with_a_dressed_chest();
    let still_the_picture = !gameplay_screen(c.app_mut()).1.inventory.slots_view;

    let map = the_painted_picture(&mut c);
    let chest = a_point_painted_for(&map, 0x0202);
    let at = on_screen(&mut c, chest);
    let picture = shipped(&mut c, PAPER_DOLL_DRAG_MASK);
    let lands_on_the_picture = {
        let Target::Point(p) = at else {
            unreachable!("built as a point")
        };
        let (ui, _screen) = gameplay_screen(c.app_mut());
        let hit = ui
            .hit_test_screen(p.x, p.y)
            .expect("the body is under the pointer");
        hit == picture || ui.is_ancestor_of(picture, hit)
    };
    let nothing_selected_yet = c.view().world().selected.is_none();

    c.when(Player::Click(at));
    clear_requests(c.ui_outbox());
    let selected = c.view().world().selected;

    c.assert_behaviour(
        "inventory.body.a-click-on-the-picture-selects-what-is-worn-in-that-region",
        move |_| {
            still_the_picture
                && lands_on_the_picture
                && nothing_selected_yet
                && selected == Some(CHEST_ARMOUR)
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.body.a-click-on-a-bare-region-of-the-picture-selects-the-player
// ---------------------------------------------------------------------------------------------

/// A click on a part of the picture where the player is wearing nothing selects **the player**.
///
/// That is what makes an undressed character clickable at all, and it is the easiest line in the
/// whole path to lose as a "nothing there, do nothing" answer.
pub fn a_click_on_a_bare_region_of_the_picture_selects_the_player() {
    let mut c = a_client_with_a_dressed_chest();
    let map = the_painted_picture(&mut c);
    // The head, where this character wears nothing.
    let head = a_point_painted_for(&map, 0x0001);
    let at = on_screen(&mut c, head);
    let nothing_selected_yet = c.view().world().selected.is_none();

    c.when(Player::Click(at));
    clear_requests(c.ui_outbox());
    let selected = c.view().world().selected;

    c.assert_behaviour(
        "inventory.body.a-click-on-a-bare-region-of-the-picture-selects-the-player",
        move |_| nothing_selected_yet && selected == Some(CLICKED_PLAYER),
    );
    c.shutdown();
}

#[test]
fn scenario_the_shipped_picture_of_the_character_is_painted_for_every_region() {
    scenario("the_shipped_picture_of_the_character_is_painted_for_every_region");
}

#[test]
fn scenario_a_click_on_the_picture_selects_what_is_worn_in_that_region() {
    scenario("a_click_on_the_picture_selects_what_is_worn_in_that_region");
}

#[test]
fn scenario_a_click_on_a_bare_region_of_the_picture_selects_the_player() {
    scenario("a_click_on_a_bare_region_of_the_picture_selects_the_player");
}

// =============================================================================================
// The use key on something that asks first.
//
// The failure these guard against: using an altar appears to do nothing. The whole chain is the
// claim and each link of it is the shipped one: the key the shipped keymap binds to *use*, the
// question the client raises for itself, the question's own buttons under a real pointer, and what
// does and does not leave for the shard.
//
// The thing being used is a **recorded** one, arriving as the shard sent it. What it carries is
// object description and nothing else -- a name, a kind, a radius and the switch that makes it
// ask -- and the recording never carried a use for it, because the client asks locally first and
// sends only after yes.
// =============================================================================================

/// The player of this scenario, and the recorded altar.
const ALTAR_PLAYER: ObjectId = ObjectId(0x5000_0001);
const ALTAR: ObjectId = ObjectId(0x701F_9020);

/// The question's own two buttons.
const ANSWER_YES: ElementId = ElementId(0x17);
const ANSWER_NO: ElementId = ElementId(0x19);

/// The recorded description of the altar, as the shard sent it.
const RECORDED_ALTAR: &str = concat!(
    "45f7000020901f701100000003880100100401000c00000000003d00030000003d00030000000000",
    "df01f9016abc4442000070c23cdf3f41f70435bf0000000000000000f70435bf2e00000934000020",
    "590300020000000000000000000000000000000000000000300020001400416c746172206f662042",
    "61656c275a6861726f6e000056034f138000000014040000200000000000a04032000000",
);

fn bytes_of(hex: &str) -> Vec<u8> {
    assert_eq!(hex.len() % 2, 0);
    hex.as_bytes()
        .chunks_exact(2)
        .map(|p| {
            let digit = |b: u8| match b {
                b'0'..=b'9' => b - b'0',
                b'a'..=b'f' => b - b'a' + 10,
                _ => panic!("a hexadecimal digit"),
            };
            (digit(p[0]) << 4) | digit(p[1])
        })
        .collect()
}

/// A client in the world with the recorded altar beside it and the altar picked.
///
/// The premises are asserted here rather than in each scenario: the thing really arrived, it is
/// the thing the recording described, and it is the one that would be used.
fn a_client_standing_at_the_altar() -> (HeadlessClient, dereth_testkit::Peer) {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    let mut peer = dereth_testkit::Peer::attach_creating(&mut c, ALTAR_PLAYER);
    c.app_mut().objects_mut().world.player = Some(ALTAR_PLAYER);
    peer.send(&mut c, 10, bytes_of(RECORDED_ALTAR));
    c.tick(3);

    {
        let w = c.view().world();
        let altar = w.weenie(ALTAR).expect("the recorded description arrives");
        assert_eq!(
            altar.pwd.name, "Altar of Bael'Zharon",
            "the premise: it is what was recorded"
        );
        assert_eq!(
            altar.pwd.useability,
            Some(0x20),
            "and it is a thing that can be used"
        );
    }
    c.app_mut().objects_mut().world.selected = Some(ALTAR);
    c.tick(1);
    (c, peer)
}

/// The question the client has put up, if it has put one up.
fn the_question(c: &mut HeadlessClient) -> Option<ElemHandle> {
    c.view()
        .expect_app()
        .ui()
        .expect("the UI shell")
        .ui
        .dialogs
        .open_on(dereth_ui::dialog::factory::DEFAULT_QUEUE)?
        .element
}

/// What the question says.
fn the_question_says(c: &mut HeadlessClient) -> String {
    let root = the_question(c).expect("the client has asked");
    let shell = c.app_mut().ui_mut().expect("the UI shell");
    let h = shell
        .ui
        .get_child_recursive(root, dereth_ui::dialog::base::child::TEXT)
        .expect("a question binds its own text");
    shell
        .ui
        .text_element_mut(h)
        .map(|t| t.glyphs.inq_text(false))
        .unwrap_or_default()
}

/// Answer the question with a real pointer on its own button.
///
/// The point is taken from the button's own box rather than from its id, because a question is
/// put up outside the screen's own roots and naming an element there finds nothing.
fn answer_the_question(c: &mut HeadlessClient, yes: bool) {
    let root = the_question(c).expect("the client has asked");
    let at = {
        let ui = &c.view().expect_app().ui().expect("the UI shell").ui;
        let button = ui
            .get_child_recursive(root, if yes { ANSWER_YES } else { ANSWER_NO })
            .expect("the question's own button");
        let r = ui.screen_clip_box(button);
        assert!(
            r.is_valid(),
            "the button is on screen, or nothing could be clicked"
        );
        ScreenPoint::new((r.x0 + r.x1) / 2, (r.y0 + r.y1) / 2)
    };
    c.when(Player::Click(Target::Point(at)));
    c.tick(4);
    clear_requests(c.ui_outbox());
}

/// Press the key the **shipped keymap** binds to *use*.
fn press_the_use_key(c: &mut HeadlessClient) {
    let key = dereth_client::platform::window::key_from_key_code(winit::keyboard::KeyCode::KeyR)
        .expect("the host names this key");
    dereth_testkit::input_steps::press_use(c, key);
}

/// Every use of the altar this client has asked the shard for.
fn uses_of_the_altar(c: &HeadlessClient) -> usize {
    c.outbound()
        .iter()
        .filter(|r| matches!(r, Request::UseEvent(m) if m.object == ALTAR))
        .count()
}

// ---------------------------------------------------------------------------------------------
// use.confirmation.the-shipped-use-key-raises-the-question-and-the-two-answers-differ
// ---------------------------------------------------------------------------------------------

/// Pressing the shipped use key on something that asks first raises the question and sends
/// nothing; **yes** then uses it once and leaves the player busy until the shard says the use is
/// done; **no** closes the question and sends nothing at all.
///
/// Both answers are one scenario because they are the two answers to one question, and the failure
/// this guards against -- pressing the key and watching nothing happen -- is indistinguishable from
/// either of them measured alone.
pub fn the_shipped_use_key_raises_the_question_and_the_two_answers_differ() {
    // Yes.
    let (mut c, mut peer) = a_client_standing_at_the_altar();
    let nothing_asked_yet = the_question(&mut c).is_none();
    press_the_use_key(&mut c);
    let the_question_is_up = the_question(&mut c).is_some();
    let in_its_own_words = the_question_says(&mut c)
        == dereth_client_model::inventory::use_object::UsageConfirmation::PkAltar.prompt();
    let nothing_sent_while_thinking = uses_of_the_altar(&c) == 0;

    // What the client acts on is what it put the question up about, and not whatever happens to
    // be picked when the answer comes: the selection is taken away before yes is pressed.
    c.app_mut().objects_mut().world.selected = None;
    answer_the_question(&mut c, true);
    let used_once = uses_of_the_altar(&c) == 1;
    let it_really_left = c.take_wire_count(0x0036) == 1;
    let busy = c.view().world().magic.busy_count == 1;
    let the_question_is_gone = the_question(&mut c).is_none();

    peer.event(
        &mut c,
        &dereth_protocol::objects::ItemUseDone { failure_type: 0 },
    );
    c.tick(6);
    let the_shard_releases_it = c.view().world().magic.busy_count == 0;
    c.shutdown();

    // No.
    let (mut c, _peer) = a_client_standing_at_the_altar();
    press_the_use_key(&mut c);
    let asked_again = the_question(&mut c).is_some();
    answer_the_question(&mut c, false);
    let nothing_sent = uses_of_the_altar(&c) == 0;
    let not_busy = c.view().world().magic.busy_count == 0;
    let closed = the_question(&mut c).is_none();

    c.assert_behaviour(
        "use.confirmation.the-shipped-use-key-raises-the-question-and-the-two-answers-differ",
        move |_| {
            nothing_asked_yet
                && the_question_is_up
                && in_its_own_words
                && nothing_sent_while_thinking
                && used_once
                && it_really_left
                && busy
                && the_question_is_gone
                && the_shard_releases_it
                && asked_again
                && nothing_sent
                && not_busy
                && closed
        },
    );
    c.shutdown();
}

#[test]
fn scenario_the_shipped_use_key_raises_the_question_and_the_two_answers_differ() {
    scenario("the_shipped_use_key_raises_the_question_and_the_two_answers_differ");
}

// =============================================================================================
// Three things that reached their handler and were then not shown, not accepted, not consumed.
//
// Each is a whole chain and each is measured at both ends, because each half can work while the
// join fails: the shop that opened into a window nobody had raised, the chest that took the key and
// then refused the use, and the shipped pick-up key that reached dispatch and matched nothing.
//
// Every message is the recording's own, and where a claim is about what goes out, the recording
// carries that message too.
// =============================================================================================

/// The vendor panel's own page, and the floating host that has to be raised over it.
const SHOP_PAGE: ElementId = ElementId(0x1000_0062);
const FLOATING_HOST: ElementId = ElementId(0x1000_05FD);
/// The grocer the recording opens, and the index of her first shop message.
const GROCER: ObjectId = ObjectId(0x77F0_3059);
const GROCER_OPENS_AT: usize = 4152;

/// The locked chest the recording unlocks and locks again, and the two moments.
const LOCKED_CHEST: ObjectId = ObjectId(0x77F0_3053);
const UNLOCKED_AT: usize = 4114;
const RELOCKED_AT: usize = 4274;

/// The thing in the recorded corpse this pick-up is about, and a compatible stack to merge into.
const CORPSE_THING: ObjectId = ObjectId(0x8000_0A99);
const CARRIED_STACK: ObjectId = ObjectId(0x8000_F185);
const CORPSE_STACK_SIZE: u16 = 15;
/// The last of the messages that create the corpse's contents.
const CORPSE_FILLED_BY: usize = 6594;

/// What the shipped keymap calls "pick up what is picked", and the map it lives on.
const PICK_UP: dereth_input::ActionId = dereth_input::ActionId(0x1000_002C);
const SELECTION_COMMANDS: dereth_input::InputMapId = dereth_input::InputMapId(0x1000_0007);

/// Whether an element is on screen: itself visible, and every ancestor visible with it. That is
/// the only question a player asks of it.
fn drawn_on_screen(c: &mut HeadlessClient, id: ElementId) -> bool {
    let mut h = element_of(c, id);
    let (ui, _root) = gameplay_root(c.app_mut());
    loop {
        if !ui.node(h).expect("a live element").region.flags.visible {
            return false;
        }
        let Some(parent) = ui.parent(h) else {
            return true;
        };
        h = parent;
    }
}

/// Whether the client believes `id` can be opened.
fn believes_it_opens(c: &HeadlessClient, id: ObjectId) -> bool {
    c.view()
        .world()
        .weenie(id)
        .unwrap_or_else(|| panic!("{id:?} is created by the recording"))
        .pwd
        .bitfield
        & dereth_client_model::weenie::bitfield::OPENABLE
        != 0
}

/// Press the key the **shipped keymap** binds to picking up what is picked.
fn press_the_pick_up_key(c: &mut HeadlessClient) {
    let key = dereth_client::platform::window::key_from_key_code(winit::keyboard::KeyCode::KeyF)
        .expect("the host names this key");
    dereth_testkit::input_steps::press_bound(c, PICK_UP, SELECTION_COMMANDS, key);
}

/// A client that has replayed the recording as far as the corpse's contents, with the recorded
/// thing picked or nothing picked.
fn a_client_at_the_recorded_corpse(pick: Option<ObjectId>) -> HeadlessClient {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    c.when(Inbound::from_corpus(
        "long-solo-play",
        0..CORPSE_FILLED_BY + 1,
    ))
    .tick(1);
    assert!(
        c.view().world().weenie(CORPSE_THING).is_some(),
        "the premise: the recording creates the thing this pick-up is about"
    );
    // What the client acts on is what is picked, so the picking is made through the client's own
    // entry point rather than assumed from the recording.
    c.app_mut().objects_mut().world.set_selected_object(
        pick,
        false,
        &mut dereth_client_model::RecordingSink::default(),
    );
    c.tick(1);
    assert_eq!(
        c.view().world().selected,
        pick,
        "the premise: that is what is picked"
    );
    c
}

// ---------------------------------------------------------------------------------------------
// vendor.window.the-shards-own-message-puts-the-shop-on-screen-and-not-only-its-tabs
// ---------------------------------------------------------------------------------------------

/// The recording's own shop message puts the shop **on screen**, and not merely its tab strip.
///
/// Both ends are asserted, and the left one first, so that a failure on the right cannot be
/// blamed on decoding, dispatch or the model: the message names the shopkeeper the recording
/// named, exactly one shop was opened, the model says a shop is open and the window found its
/// own lists. Then the right end, which nothing measured: the shop's own page is visible and the
/// floating window that carries it has been raised.
pub fn the_shards_own_message_puts_the_shop_on_screen_and_not_only_its_tabs() {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    c.when(Inbound::from_corpus(
        "long-solo-play",
        0..GROCER_OPENS_AT + 1,
    ))
    .tick(4);

    let the_model_agrees = c.view().world().shop.vendor_id == Some(GROCER)
        && c.view().interaction().stats.vendor_opens == 1
        && dereth_client::vendor_view::shop(c.view().world()).open
        && c.view().expect_app().hud().panels.vendor.bound();

    let the_page_is_visible = {
        let h = element_of(&c, SHOP_PAGE);
        let (ui, _root) = gameplay_root(c.app_mut());
        ui.node(h).expect("a live element").region.flags.visible
    };
    let the_host_is_raised = drawn_on_screen(&mut c, FLOATING_HOST);
    let the_shop_is_really_on_screen = drawn_on_screen(&mut c, SHOP_PAGE);

    c.assert_behaviour(
        "vendor.window.the-shards-own-message-puts-the-shop-on-screen-and-not-only-its-tabs",
        move |_| {
            the_model_agrees
                && the_page_is_visible
                && the_host_is_raised
                && the_shop_is_really_on_screen
        },
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// container.ground.the-shards-unlock-reaches-the-chest-and-the-relock-follows-it
// ---------------------------------------------------------------------------------------------

/// The shard saying a chest is unlocked reaches the chest, and saying it is locked again reaches
/// it too.
///
/// The control is the same run: before the unlock arrives the client believes the chest is
/// locked, so "it opens" afterwards cannot be the state the chest was created with. The relock
/// is the other half and it is what makes this a live receiver rather than a one-way switch --
/// a client that dropped these leaves one stale flag, and the chest is dead for the rest of the
/// session however many times the player uses the right key on it.
pub fn the_shards_unlock_reaches_the_chest_and_the_relock_follows_it() {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    c.when(Inbound::from_corpus("long-solo-play", 0..UNLOCKED_AT))
        .tick(1);
    let locked_to_begin_with = !believes_it_opens(&c, LOCKED_CHEST);

    c.when(Inbound::from_corpus(
        "long-solo-play",
        UNLOCKED_AT..UNLOCKED_AT + 1,
    ))
    .tick(1);
    let the_unlock_landed = believes_it_opens(&c, LOCKED_CHEST);

    c.when(Inbound::from_corpus(
        "long-solo-play",
        UNLOCKED_AT + 1..RELOCKED_AT + 1,
    ))
    .tick(1);
    let the_relock_landed = !believes_it_opens(&c, LOCKED_CHEST);

    c.assert_behaviour(
        "container.ground.the-shards-unlock-reaches-the-chest-and-the-relock-follows-it",
        move |_| locked_to_begin_with && the_unlock_landed && the_relock_landed,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.pickup.the-shipped-key-puts-what-is-picked-into-the-players-own-pack
// ---------------------------------------------------------------------------------------------

/// Pressing the key the shipped keymap binds to picking things up puts what is picked into the
/// player's own pack.
///
/// The key had resolved correctly all along and produced its action; what was missing was
/// anything that answered it, so the action was swept away and nothing went out for any object,
/// ever. The message it must produce is one the recording itself carries for the same thing.
pub fn the_shipped_key_puts_what_is_picked_into_the_players_own_pack() {
    let mut c = a_client_at_the_recorded_corpse(Some(CORPSE_THING));
    let player = c
        .view()
        .world()
        .player
        .expect("the recording names its own player");
    let before = c.view().interaction().stats.pick_ups;

    let mark = c.outbound().len();
    press_the_pick_up_key(&mut c);
    c.tick(2);
    let sent: Vec<Request> = c.outbound()[mark..].to_vec();

    let the_action_was_answered = c.view().interaction().stats.pick_ups == before + 1;
    let it_went_into_the_pack = sent.iter().any(|r| {
        matches!(r, Request::PutItemInContainer(m)
            if m.item == CORPSE_THING && m.container == player)
    });

    c.assert_behaviour(
        "inventory.pickup.the-shipped-key-puts-what-is-picked-into-the-players-own-pack",
        move |_| the_action_was_answered && it_went_into_the_pack,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.pickup.the-shipped-key-carries-the-picked-stacks-own-count-into-the-merge
// ---------------------------------------------------------------------------------------------

/// When what is picked is a stack and the player is already carrying a compatible one, the same
/// key merges them, and it carries the count the picking itself worked out rather than a fresh
/// empty one.
///
/// The count is seeded by the picking, before the key is ever pressed, which is asserted as the
/// premise: a client that started the merge from nothing would send a zero and the player would
/// watch the stack not move.
pub fn the_shipped_key_carries_the_picked_stacks_own_count_into_the_merge() {
    let mut c = HeadlessClient::new(ClientSpec::gameplay(4));
    c.when(Inbound::from_corpus(
        "long-solo-play",
        0..CORPSE_FILLED_BY + 1,
    ))
    .tick(1);
    let player = c
        .view()
        .world()
        .player
        .expect("the recording names its own player");

    // The recording's own corpse thing, with its count and a compatible carried stack made
    // explicit: that is the one branch whose amount is the thing this scenario is about, and a
    // plain corpse thing would only exercise the plain move again.
    {
        let world = &mut c.app_mut().objects_mut().world;
        let source = world
            .weenie_mut(CORPSE_THING)
            .expect("the recorded corpse thing");
        source.pwd.wcid = 0xF185;
        source.pwd.stack_size = Some(CORPSE_STACK_SIZE);
        source.pwd.max_stack_size = Some(100);

        let mut target = dereth_client_model::Weenie::new(CARRIED_STACK);
        target.pwd = PublicWeenieDesc {
            name: "a compatible carried stack".into(),
            wcid: 0xF185,
            stack_size: Some(20),
            max_stack_size: Some(100),
            container_id: Some(player),
            ..PublicWeenieDesc::default()
        };
        target.valid = true;
        world.tables.weenies.insert(CARRIED_STACK, target);
        world.view_object_contents(
            player,
            &[dereth_protocol::types::ContentProfile {
                iid: CARRIED_STACK,
                container_properties: 0,
            }],
            &mut dereth_client_model::NullSink,
        );
    }

    c.app_mut().objects_mut().world.set_selected_object(
        Some(CORPSE_THING),
        false,
        &mut dereth_client_model::RecordingSink::default(),
    );
    c.tick(1);
    let the_count_was_seeded_by_the_picking = c.view().world().split
        == dereth_client_model::inventory::SplitState::whole_stack(u32::from(CORPSE_STACK_SIZE));

    let mark = c.outbound().len();
    press_the_pick_up_key(&mut c);
    c.tick(2);
    let sent: Vec<Request> = c.outbound()[mark..].to_vec();
    let merged = matches!(
        sent.as_slice(),
        [Request::StackableMerge(m)]
            if m.merge_from == CORPSE_THING
                && m.merge_to == CARRIED_STACK
                && m.amount == i32::from(CORPSE_STACK_SIZE)
    );

    c.assert_behaviour(
        "inventory.pickup.the-shipped-key-carries-the-picked-stacks-own-count-into-the-merge",
        move |_| the_count_was_seeded_by_the_picking && merged,
    );
    c.shutdown();
}

// ---------------------------------------------------------------------------------------------
// inventory.pickup.the-shipped-key-with-nothing-picked-sends-nothing
// ---------------------------------------------------------------------------------------------

/// With nothing picked, the same key is **not** answered at all and nothing goes out.
///
/// Without this a client that picked up whatever it found, including nothing at all, would pass
/// the two scenarios above.
pub fn the_shipped_key_with_nothing_picked_sends_nothing() {
    let mut c = a_client_at_the_recorded_corpse(None);
    let before = c.view().interaction().stats.pick_ups;

    let mark = c.outbound().len();
    press_the_pick_up_key(&mut c);
    c.tick(2);
    let sent: Vec<Request> = c.outbound()[mark..].to_vec();

    let not_answered = c.view().interaction().stats.pick_ups == before;
    let nothing_went_out = !sent
        .iter()
        .any(|r| matches!(r, Request::PutItemInContainer(_)));

    c.assert_behaviour(
        "inventory.pickup.the-shipped-key-with-nothing-picked-sends-nothing",
        move |_| not_answered && nothing_went_out,
    );
    c.shutdown();
}

